insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (95, 6, 111, 121, 'سورة الأنعام ١١١ – ١٢١', '«شياطين الإنس والجن»، «أفغير الله أبتغي حكماً»، و«فكلوا مما ذُكر اسم الله عليه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 95) = $j$[{"lbl": "الآيات ١١١ – ١١٣", "q": "۞وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَـٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ كُلَّ شَيۡءٖ قُبُلٗا مَّا كَانُواْ لِيُؤۡمِنُوٓاْ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكۡثَرَهُمۡ يَجۡهَلُونَ ﴿١١١﴾ وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ ﴿١١٢﴾ وَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ وَلِيَقۡتَرِفُواْ مَا هُم مُّقۡتَرِفُونَ ﴿١١٣﴾", "w": [["الملائكة", "أجسام نورانية يعمرون السماوات، عباد مكرمون لا يعصون الله ويفعلون ما يؤمرون، لا يوصفون بذكورة ولا أنوثة."], ["الموتى", "جمع ميت: من فارقته الحياة، أي خرجت منه روحه."], ["قبلاً", "معاينة."], ["يجهلون", "عظمة الله وقدرته وتدبيره وحكمته."], ["شياطين", "جمع شيطان، وهو من خبث وتمرّد من الجن والإنس."], ["يوحي بعضهم", "يُعلم بعضهم بعضاً بطريق سريع خفي."], ["زخرف القول", "الكذب المحسّن المزيّن."], ["غروراً", "للتغرير بالإنسان."], ["يفترون", "يكذبون."], ["ولتصغى إليه", "تميل إليه."], ["وليقترفوا", "وليرتكبوا الذنوب والمعاصي."]], "m": "ما زال السياق في المطالبين بالآيات الكونية ليؤمنوا، فأخبر الله أنه لو نزّل إليهم الملائكة من السماء، وكلّمهم الموتى فقالوا لهم: لا إله إلا الله محمد رسول الله، وحشر عليهم كل شيء يعاينونه قبيلاً بعد قبيل، ما كانوا ليؤمنوا إلا أن يشاء الله، ولكن أكثرهم يجهلون أن الهداية بيد الله لا بأيديهم كما يزعمون. وكما كان لك يا رسولنا من هؤلاء أعداء يجادلونك ويحاربونك، جعلنا لكل نبي عدواً شياطين الإنس والجن، يوحي بعضهم إلى بعض القول المزيّن بالباطل المحسّن بالكذب للتغرير والتضليل، ولو شاء ربك ما فعلوه، فذرهم وما يفترون. وكان ذلك الإيحاء ليغترّ به المشركون، ولتميل إليه قلوب الذين لا يؤمنون بالآخرة، وليرضوه ويقتنعوا به لأنه مموّه مزيّن، وليقترفوا نتيجة ذلك من أنواع الكفر والشرك والمعاصي ما هم مقترفون.", "h": ["ما شاء الله كان وما لم يشأ لم يكن أبداً، وبهذا تقرّرت ربوبيته وألوهيته للأولين والآخرين.", "تسلية الرسول ﷺ وكل داعٍ إلى الله تعالى بإعلامه أنه ما من نبي ولا داعٍ إلا وله أعداء من الجن والإنس يحاربونه حتى ينصره الله عليهم.", "التحذير من التمويه والتغرير، فإن أمضى سلاح للشياطين هو التزيين والتغرير.", "القلوب الفارغة من الإيمان بالله ووعده ووعيده في الدار الآخرة أكثر القلوب ميلاً إلى الباطل والشر والفساد."], "k": "«زخرف القول غروراً»… كم من كلام مزيّن سمعته فمال إليه قلبي؛ فهل أزنه بميزان الوحي قبل أن أرضاه؟"}, {"lbl": "الآيات ١١٤ – ١١٧", "q": "أَفَغَيۡرَ ٱللَّهِ أَبۡتَغِي حَكَمٗا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلٗاۚ وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلٞ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ ﴿١١٤﴾ وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿١١٥﴾ وَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ ﴿١١٦﴾ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ﴿١١٧﴾", "w": [["أبتغي", "أطلب."], ["حكماً", "الحكم: الحاكم ومن يتحاكم إليه الناس."], ["أنزل إليكم الكتاب", "أنزله لأجلكم لتهتدوا به فتكملوا وتسعدوا."], ["مفصّلاً", "مبيّناً لا خفاء فيه ولا غموض."], ["والذين آتيناهم الكتاب", "علماء اليهود والنصارى."], ["الممترين", "الشاكّين، إذ الامتراء: الشك."], ["صدقاً وعدلاً", "صدقاً في الأخبار، فكل ما أخبر به القرآن صدق، وعدلاً في الأحكام، فليس في القرآن حكم جور وظلم أبداً، بل كل أحكامه عادلة."], ["لا مبدّل لكلماته", "لا مغيّر لها، لا بالزيادة والنقصان، ولا بالتقديم والتأخير."], ["السميع العليم", "السميع لأقوال العباد، العليم بأعمالهم ونياتهم، وسيجزيهم بذلك."], ["سبيل الله", "الإسلام، إذ هو المفضي بالمسلم إلى رضوان الله والكرامة في جواره."], ["يخرصون", "يكذبون الكذب الناتج عن الحزر والتخمين."], ["من يضل", "بمن يضل."], ["بالمهتدين", "في سيرهم إلى رضوان الله باتباع الإسلام الذي هو سبيل الله."]], "m": "كان مراد المشركين من طلب الآية أن يحكموا بها على صحة نبوته ﷺ، وما كان هذا منهم إلا من وسوسة الشياطين وتزيينها، ليواصلوا ذنوبهم فلا يؤمنون. فعلّم الله رسوله أن يقول لهم: أفأميل إلى باطلكم فأطلب غير الله حكماً بيني وبينكم، وهو الذي أنزل إليكم الكتاب مفصّلاً؟ فأي آية تغلب القرآن وهو آلاف الآيات؟ والذين آتيناهم الكتاب من علماء اليهود والنصارى يعلمون أنه منزل من ربك بالحق، فامضِ في طريق دعوتك ولا تكوننّ من الممترين. وتمّت كلمة ربك في هذا القرآن صدقاً في كل ما يحمله من أخبار، ومن ذلك نصرك وهزيمة أعدائك، وعدلاً في أحكامه، لا يستطيع أحد تبديلها، وهو السميع العليم، فلن يكون إلا مراده. وإن تطع أكثر من في الأرض فتأخذ بآرائهم وتستجيب لاقتراحاتهم يضلّوك عن سبيل الله، لأن أكثرهم لا بصيرة له ولا علم، وكل ما يقولونه هوى نفس ووسواس شيطان، إن يتبعون إلا الظن وإن هم إلا يخرصون، إن ربك هو أعلم من يضل عن سبيله وهو أعلم بالمهتدين.", "h": ["حرمة وبطلان التحاكم إلى غير الوحي الإلهي.", "تقرير صحة الدعوة الإسلامية بأمرين: الأول القرآن الكريم، والثاني شهادة أهل الكتاب ممن أسلموا كعبد الله بن سلام وأصحمة النجاشي وغيرهما.", "ميزة القرآن الكريم: أن أخباره كلها صدق، وأحكامه كلها عدل.", "وعود الله تعالى لا تتخلّف أبداً، ولا تتبدّل بتقديم ولا تأخير.", "اتباع أكثر الناس يؤدي إلى الضلال، فلذا لا يُتّبع إلا أهل العلم الراسخون فيه، لقوله تعالى: «ولا تتبعانّ سبيل الذين لا يعلمون»."], "k": "«وإن تطع أكثر من في الأرض يضلّوك»… هل أتّبع ما عليه أكثر الناس، أم ما عليه الدليل؟"}, {"lbl": "الآيات ١١٨ – ١٢١", "q": "فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ ﴿١١٨﴾ وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ ﴿١١٩﴾ وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ ﴿١٢٠﴾ وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقٞۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ ﴿١٢١﴾", "w": [["مما ذُكر اسم الله عليه", "ما قيل عند ذبحه أو نحره: بسم الله والله أكبر."], ["فصّل لكم ما حرّم عليكم", "بيّن لكم ما حرّم عليكم مما أحلّ لكم."], ["إلا ما اضطررتم إليه", "ما ألجأتكم إليه الضرورة، وهي خوف الضرر من الجوع."], ["المعتدين", "المتجاوزين الحلال إلى الحرام، والحق إلى الباطل."], ["وذروا ظاهر الإثم", "اتركوا الإثم الظاهر والباطن، وهو كل ضارّ فاسد قبيح."], ["يقترفون", "يكسبون الآثام والذنوب."], ["وإنه لفسق", "الأكل مما لم يُذكر اسم الله عليه فسق عن طاعة الله تعالى."], ["إلى أوليائهم ليجادلوكم", "أي من الإنس، ليخاصموكم في ترك الأكل من الميتة."], ["لمشركون", "حيث أحلّوا لكم ما حرّم عليكم فاعتقدتم حلّه، فكنتم بذلك عابديهم، وعبادة غير الله شرك."]], "m": "مما أوحت به شياطين الجن إلى إخوانهم من شياطين الإنس أن قالوا للرسول ﷺ والمؤمنين: كيف تأكلون ما تقتلونه أنتم وتمتنعون عن أكل ما يقتله الله؟ فأنزل الله: فكلوا مما ذُكر اسم الله عليه إن كنتم بآياته مؤمنين، ولا تستجيبوا لما يقوله المشركون. وأي شيء يمنعكم من الأكل مما ذُكر اسم الله عليه، وقد بيّن لكم غاية التبيين ما حرّم عليكم من المطاعم إلا ما ألجأتكم إليه الضرورة، كمن خاف على نفسه الهلاك من شدة الجوع؟ وإن كثيراً من الناس ليُضلّون غيرهم بأهوائهم بغير علم، فيحلّون ويحرّمون بلا علم، وهم في ذلك معتدون، لأن التحليل والتحريم حق الرب تعالى، إن ربك هو أعلم بالمعتدين وسيجازيهم. وذروا ظاهر الإثم كالزنى العلني، وباطنه كالذنوب الخفية، وهو شامل لأعمال القلوب والجوارح، إن الذين يكسبون الإثم سيُجزون يوم القيامة بما كانوا يقترفون، ولا ينجو إلا من تاب. ولا تأكلوا مما لم يُذكر اسم الله عليه من ذبائح المشركين والمجوس، وإنه لفسق وخروج عن طاعة الله، لما فيه من الرضا بذكر اسم الآلهة التي تُعبد من دونه، وإن الشياطين ليوحون إلى أوليائهم من الإنس بمثل قولهم: كيف تحرّمون ما قتل الله وتحلّون ما قتلتم أنتم؟ ليجادلوكم، وإن أطعتموهم إنكم لمشركون.", "h": ["حِلّ الأكل من ذبائح المسلمين.", "وجوب ذكر اسم الله على بهيمة الأنعام عند تذكيتها.", "حرمة اتباع الأهواء، ووجوب اتباع العلماء.", "وجوب ترك الإثم ظاهراً كان أو باطناً، وسواء كان من أعمال القلوب أو أعمال الجوارح.", "حرمة الأكل من ذبائح المشركين والمجوس والملاحدة البلاشفة الشيوعيين.", "اعتقاد حِلّ طاعة الشياطين شرك، والعياذ بالله تعالى."], "k": "«وذروا ظاهر الإثم وباطنه»… أتجنّب الذنب أمام الناس، فهل أتجنّبه كذلك في خلوتي وفي قلبي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 95;
insert into public.tdb_cards(topic, i, body) select 95, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١١ – ١١٣", "q": "۞وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَـٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ كُلَّ شَيۡءٖ قُبُلٗا مَّا كَانُواْ لِيُؤۡمِنُوٓاْ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكۡثَرَهُمۡ يَجۡهَلُونَ ﴿١١١﴾ وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ ﴿١١٢﴾ وَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ وَلِيَقۡتَرِفُواْ مَا هُم مُّقۡتَرِفُونَ ﴿١١٣﴾", "w": [["الملائكة", "أجسام نورانية يعمرون السماوات، عباد مكرمون لا يعصون الله ويفعلون ما يؤمرون، لا يوصفون بذكورة ولا أنوثة."], ["الموتى", "جمع ميت: من فارقته الحياة، أي خرجت منه روحه."], ["قبلاً", "معاينة."], ["يجهلون", "عظمة الله وقدرته وتدبيره وحكمته."], ["شياطين", "جمع شيطان، وهو من خبث وتمرّد من الجن والإنس."], ["يوحي بعضهم", "يُعلم بعضهم بعضاً بطريق سريع خفي."], ["زخرف القول", "الكذب المحسّن المزيّن."], ["غروراً", "للتغرير بالإنسان."], ["يفترون", "يكذبون."], ["ولتصغى إليه", "تميل إليه."], ["وليقترفوا", "وليرتكبوا الذنوب والمعاصي."]], "m": "ما زال السياق في المطالبين بالآيات الكونية ليؤمنوا، فأخبر الله أنه لو نزّل إليهم الملائكة من السماء، وكلّمهم الموتى فقالوا لهم: لا إله إلا الله محمد رسول الله، وحشر عليهم كل شيء يعاينونه قبيلاً بعد قبيل، ما كانوا ليؤمنوا إلا أن يشاء الله، ولكن أكثرهم يجهلون أن الهداية بيد الله لا بأيديهم كما يزعمون. وكما كان لك يا رسولنا من هؤلاء أعداء يجادلونك ويحاربونك، جعلنا لكل نبي عدواً شياطين الإنس والجن، يوحي بعضهم إلى بعض القول المزيّن بالباطل المحسّن بالكذب للتغرير والتضليل، ولو شاء ربك ما فعلوه، فذرهم وما يفترون. وكان ذلك الإيحاء ليغترّ به المشركون، ولتميل إليه قلوب الذين لا يؤمنون بالآخرة، وليرضوه ويقتنعوا به لأنه مموّه مزيّن، وليقترفوا نتيجة ذلك من أنواع الكفر والشرك والمعاصي ما هم مقترفون.", "h": ["ما شاء الله كان وما لم يشأ لم يكن أبداً، وبهذا تقرّرت ربوبيته وألوهيته للأولين والآخرين.", "تسلية الرسول ﷺ وكل داعٍ إلى الله تعالى بإعلامه أنه ما من نبي ولا داعٍ إلا وله أعداء من الجن والإنس يحاربونه حتى ينصره الله عليهم.", "التحذير من التمويه والتغرير، فإن أمضى سلاح للشياطين هو التزيين والتغرير.", "القلوب الفارغة من الإيمان بالله ووعده ووعيده في الدار الآخرة أكثر القلوب ميلاً إلى الباطل والشر والفساد."], "k": "«زخرف القول غروراً»… كم من كلام مزيّن سمعته فمال إليه قلبي؛ فهل أزنه بميزان الوحي قبل أن أرضاه؟"}, {"lbl": "الآيات ١١٤ – ١١٧", "q": "أَفَغَيۡرَ ٱللَّهِ أَبۡتَغِي حَكَمٗا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلٗاۚ وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلٞ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ ﴿١١٤﴾ وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿١١٥﴾ وَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ ﴿١١٦﴾ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ﴿١١٧﴾", "w": [["أبتغي", "أطلب."], ["حكماً", "الحكم: الحاكم ومن يتحاكم إليه الناس."], ["أنزل إليكم الكتاب", "أنزله لأجلكم لتهتدوا به فتكملوا وتسعدوا."], ["مفصّلاً", "مبيّناً لا خفاء فيه ولا غموض."], ["والذين آتيناهم الكتاب", "علماء اليهود والنصارى."], ["الممترين", "الشاكّين، إذ الامتراء: الشك."], ["صدقاً وعدلاً", "صدقاً في الأخبار، فكل ما أخبر به القرآن صدق، وعدلاً في الأحكام، فليس في القرآن حكم جور وظلم أبداً، بل كل أحكامه عادلة."], ["لا مبدّل لكلماته", "لا مغيّر لها، لا بالزيادة والنقصان، ولا بالتقديم والتأخير."], ["السميع العليم", "السميع لأقوال العباد، العليم بأعمالهم ونياتهم، وسيجزيهم بذلك."], ["سبيل الله", "الإسلام، إذ هو المفضي بالمسلم إلى رضوان الله والكرامة في جواره."], ["يخرصون", "يكذبون الكذب الناتج عن الحزر والتخمين."], ["من يضل", "بمن يضل."], ["بالمهتدين", "في سيرهم إلى رضوان الله باتباع الإسلام الذي هو سبيل الله."]], "m": "كان مراد المشركين من طلب الآية أن يحكموا بها على صحة نبوته ﷺ، وما كان هذا منهم إلا من وسوسة الشياطين وتزيينها، ليواصلوا ذنوبهم فلا يؤمنون. فعلّم الله رسوله أن يقول لهم: أفأميل إلى باطلكم فأطلب غير الله حكماً بيني وبينكم، وهو الذي أنزل إليكم الكتاب مفصّلاً؟ فأي آية تغلب القرآن وهو آلاف الآيات؟ والذين آتيناهم الكتاب من علماء اليهود والنصارى يعلمون أنه منزل من ربك بالحق، فامضِ في طريق دعوتك ولا تكوننّ من الممترين. وتمّت كلمة ربك في هذا القرآن صدقاً في كل ما يحمله من أخبار، ومن ذلك نصرك وهزيمة أعدائك، وعدلاً في أحكامه، لا يستطيع أحد تبديلها، وهو السميع العليم، فلن يكون إلا مراده. وإن تطع أكثر من في الأرض فتأخذ بآرائهم وتستجيب لاقتراحاتهم يضلّوك عن سبيل الله، لأن أكثرهم لا بصيرة له ولا علم، وكل ما يقولونه هوى نفس ووسواس شيطان، إن يتبعون إلا الظن وإن هم إلا يخرصون، إن ربك هو أعلم من يضل عن سبيله وهو أعلم بالمهتدين.", "h": ["حرمة وبطلان التحاكم إلى غير الوحي الإلهي.", "تقرير صحة الدعوة الإسلامية بأمرين: الأول القرآن الكريم، والثاني شهادة أهل الكتاب ممن أسلموا كعبد الله بن سلام وأصحمة النجاشي وغيرهما.", "ميزة القرآن الكريم: أن أخباره كلها صدق، وأحكامه كلها عدل.", "وعود الله تعالى لا تتخلّف أبداً، ولا تتبدّل بتقديم ولا تأخير.", "اتباع أكثر الناس يؤدي إلى الضلال، فلذا لا يُتّبع إلا أهل العلم الراسخون فيه، لقوله تعالى: «ولا تتبعانّ سبيل الذين لا يعلمون»."], "k": "«وإن تطع أكثر من في الأرض يضلّوك»… هل أتّبع ما عليه أكثر الناس، أم ما عليه الدليل؟"}, {"lbl": "الآيات ١١٨ – ١٢١", "q": "فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ ﴿١١٨﴾ وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ ﴿١١٩﴾ وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ ﴿١٢٠﴾ وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقٞۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ ﴿١٢١﴾", "w": [["مما ذُكر اسم الله عليه", "ما قيل عند ذبحه أو نحره: بسم الله والله أكبر."], ["فصّل لكم ما حرّم عليكم", "بيّن لكم ما حرّم عليكم مما أحلّ لكم."], ["إلا ما اضطررتم إليه", "ما ألجأتكم إليه الضرورة، وهي خوف الضرر من الجوع."], ["المعتدين", "المتجاوزين الحلال إلى الحرام، والحق إلى الباطل."], ["وذروا ظاهر الإثم", "اتركوا الإثم الظاهر والباطن، وهو كل ضارّ فاسد قبيح."], ["يقترفون", "يكسبون الآثام والذنوب."], ["وإنه لفسق", "الأكل مما لم يُذكر اسم الله عليه فسق عن طاعة الله تعالى."], ["إلى أوليائهم ليجادلوكم", "أي من الإنس، ليخاصموكم في ترك الأكل من الميتة."], ["لمشركون", "حيث أحلّوا لكم ما حرّم عليكم فاعتقدتم حلّه، فكنتم بذلك عابديهم، وعبادة غير الله شرك."]], "m": "مما أوحت به شياطين الجن إلى إخوانهم من شياطين الإنس أن قالوا للرسول ﷺ والمؤمنين: كيف تأكلون ما تقتلونه أنتم وتمتنعون عن أكل ما يقتله الله؟ فأنزل الله: فكلوا مما ذُكر اسم الله عليه إن كنتم بآياته مؤمنين، ولا تستجيبوا لما يقوله المشركون. وأي شيء يمنعكم من الأكل مما ذُكر اسم الله عليه، وقد بيّن لكم غاية التبيين ما حرّم عليكم من المطاعم إلا ما ألجأتكم إليه الضرورة، كمن خاف على نفسه الهلاك من شدة الجوع؟ وإن كثيراً من الناس ليُضلّون غيرهم بأهوائهم بغير علم، فيحلّون ويحرّمون بلا علم، وهم في ذلك معتدون، لأن التحليل والتحريم حق الرب تعالى، إن ربك هو أعلم بالمعتدين وسيجازيهم. وذروا ظاهر الإثم كالزنى العلني، وباطنه كالذنوب الخفية، وهو شامل لأعمال القلوب والجوارح، إن الذين يكسبون الإثم سيُجزون يوم القيامة بما كانوا يقترفون، ولا ينجو إلا من تاب. ولا تأكلوا مما لم يُذكر اسم الله عليه من ذبائح المشركين والمجوس، وإنه لفسق وخروج عن طاعة الله، لما فيه من الرضا بذكر اسم الآلهة التي تُعبد من دونه، وإن الشياطين ليوحون إلى أوليائهم من الإنس بمثل قولهم: كيف تحرّمون ما قتل الله وتحلّون ما قتلتم أنتم؟ ليجادلوكم، وإن أطعتموهم إنكم لمشركون.", "h": ["حِلّ الأكل من ذبائح المسلمين.", "وجوب ذكر اسم الله على بهيمة الأنعام عند تذكيتها.", "حرمة اتباع الأهواء، ووجوب اتباع العلماء.", "وجوب ترك الإثم ظاهراً كان أو باطناً، وسواء كان من أعمال القلوب أو أعمال الجوارح.", "حرمة الأكل من ذبائح المشركين والمجوس والملاحدة البلاشفة الشيوعيين.", "اعتقاد حِلّ طاعة الشياطين شرك، والعياذ بالله تعالى."], "k": "«وذروا ظاهر الإثم وباطنه»… أتجنّب الذنب أمام الناس، فهل أتجنّبه كذلك في خلوتي وفي قلبي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (96, 6, 122, 135, 'سورة الأنعام ١٢٢ – ١٣٥', '«أوَمن كان ميتاً فأحييناه»، «فمن يرد الله أن يهديه يشرح صدره»، و«اعملوا على مكانتكم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 96) = $j$[{"lbl": "الآيات ١٢٢ – ١٢٤", "q": "أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورٗا يَمۡشِي بِهِۦ فِي ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِي ٱلظُّلُمَٰتِ لَيۡسَ بِخَارِجٖ مِّنۡهَاۚ كَذَٰلِكَ زُيِّنَ لِلۡكَٰفِرِينَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٢٢﴾ وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ ﴿١٢٣﴾ وَإِذَا جَآءَتۡهُمۡ ءَايَةٞ قَالُواْ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَآ أُوتِيَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ سَيُصِيبُ ٱلَّذِينَ أَجۡرَمُواْ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٞ شَدِيدُۢ بِمَا كَانُواْ يَمۡكُرُونَ ﴿١٢٤﴾", "w": [["ميتاً", "الميت فاقد الروح، والمراد روح الإيمان."], ["أحييناه", "جعلناه حياً بروح الإيمان."], ["مثله", "صفته ونعته: امرؤ في الظلمات ليس بخارج منها."], ["قرية", "مدينة كبيرة."], ["ليمكروا فيها", "بفعل المنكرات والدعوة إلى ارتكابها بأسلوب الخديعة والاحتيال."], ["وما يمكرون إلا بأنفسهم", "لأن عاقبة المكر تعود على الماكر نفسه، لآية «ولا يحيق المكر السيئ إلا بأهله»."], ["وإذا جاءتهم آية", "أي من القرآن الكريم تدعوهم إلى الحق."], ["صغار", "الذل والهوان."]], "m": "ما زال السياق في حرب العادلين بربهم الذين يزيّن لهم الشيطان تحريم ما أحل الله وتحليل ما حرّم: أوَمن كان ميتاً بالشرك والكفر فأحييناه بالإيمان والتوحيد وجعلنا له نوراً يمشي به في الناس، وهو عمر بن الخطاب أو عمار بن ياسر، كمن مثله في ظلمات الشرك والكفر والمعاصي ليس بخارج منها، وهو أبو جهل؟ لا يستويان، فكيف أطاع المشركون أبا جهل وعصوا عمر؟ لأن الكافرين لظلمة نفوسهم واتباع أهوائهم زُيّن لهم عملهم الباطل، على سنة الله في أن من أحب شيئاً وغالى في حبه على غير هدى أصبح في نظره زيناً وهو شين. وكذلك جعلنا في كل قرية أكابر مجرميها ليمكروا فيها، يفسدون عقائد الناس وأخلاقهم بزخرف القول والخداع، وما يمكرون إلا بأنفسهم إذ ستحل بهم العقوبة، وما يشعرون. وإذا جاءتهم آية من القرآن تدعوهم إلى تصديق الرسول قالوا: لن نؤمن حتى نؤتى مثل ما أوتي رسل الله من المعجزات كعصا موسى، فردّ الله عليهم هذا العلو والتكبر: الله أعلم حيث يجعل رسالته، يجعلها في القلوب المشرقة والنفوس الزكية لا في القلوب المظلمة والنفوس الخبيثة. سيصيب الذين أجرموا صغار عند الله يوم يلقونه، وعذاب شديد بما كانوا يمكرون بالناس بتضليلهم وإفساد قلوبهم.", "h": ["الإيمان حياة والكفر موت، المؤمن يعيش في نور والكافر في ظلمات.", "بيان سنة الله تعالى في تزيين الأعمال القبيحة.", "قلّما تخلو مدينة من مجرمين يمكرون فيها.", "عاقبة المكر عائدة على الماكر نفسه.", "بيان تعنّت المشركين في مكة على عهد نزول القرآن.", "الرسالة توهب لا تكتسب.", "بيان عقوبة أهل الإجرام في الأرض."], "k": "«وجعلنا له نوراً يمشي به في الناس»… هل يرى الناس في مشيي بينهم أثر نور الإيمان؟"}, {"lbl": "الآيات ١٢٥ – ١٢٨", "q": "فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ ﴿١٢٥﴾ وَهَٰذَا صِرَٰطُ رَبِّكَ مُسۡتَقِيمٗاۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَذَّكَّرُونَ ﴿١٢٦﴾ ۞لَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٢٧﴾ وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا يَٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِيَآؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٖ وَبَلَغۡنَآ أَجَلَنَا ٱلَّذِيٓ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ ﴿١٢٨﴾", "w": [["شرح صدره", "توسعته لقبول الحق وحمل الوارد عليه من أنوار الإيمان، وعلامة ذلك: الإنابة إلى دار الخلود، والتجافي عن دار الغرور، والاستعداد للموت قبل نزوله."], ["حرجاً", "ضيقاً لا يتسع لقبول الحق ولا لنور الإيمان."], ["كأنما يصّعّد", "يصعب عليه قبول الإيمان حتى كأنه يتكلّف الصعود إلى السماء."], ["الرجس", "النجس وما لا خير فيه كالشيطان."], ["فصّلنا الآيات", "بيّناها وأوضحناها غاية البيان والتوضيح."], ["يذّكرون", "يتذكّرون فيتّعظون."], ["دار السلام", "الجنة، والسلام اسم من أسماء الله تعالى، فهي مضافة إلى الله."], ["استكثرتم", "أي من إضلال الإنس وإغوائهم."], ["استمتع بعضنا ببعض", "انتفع كل منا بصاحبه، أي تبادلنا المنافع بيننا حتى الموت."], ["أجلنا الذي أجّلت لنا", "الوقت الذي وقّت لنا، وهو أجل موتنا فمتنا."], ["مثواكم", "مأواكم ومقرّ بقائكم وإقامتكم."], ["حكيم عليم", "حكيم في وضع كل شيء في موضعه، فلا يخلّد أهل الإيمان في النار ولا يُخرج أهل الكفر منها، عليم بأهل الإيمان وأهل الكفر."]], "m": "بعد ذلك البيان لطريق الهداية، أعلم الله عباده أن الهداية والإضلال بيده، يهدي من يشاء برحمته ويضل من يشاء بعدله، ولكلٍّ منهما سنن: فمن طلب الهداية صادقاً علم الله ذلك منه فسهّل له طرقها، ومن ذلك أنه يشرح صدره لقبول الإيمان وأنواره فيكمل ويسعد، ومن طلب الغواية صادقاً هيّأ له أسبابها، فجعل صدره ضيقاً حرجاً لا يتسع لقبول الإيمان، كأنما يتكلّف الصعود إلى السماء وما هو بقادر. كذلك يجعل الله الرجس، كل ما لا خير فيه من الكبر والحسد والشرك والشيطان، على الذين لا يؤمنون، لقبول المحل له نتيجة خلوّه من الإيمان. وهذا صراط ربك مستقيماً فالزمه، فإنه يفضي بك إلى كرامة ربك وجواره، قد فصّلنا الآيات لقوم يذّكرون فيؤمنون ويعملون، لهم دار السلام عند ربهم، وهو وليهم بالنصر في الدنيا والإنعام في الآخرة بما كانوا يعملون. ويوم يحشرهم جميعاً إنسهم وجنهم: يا معشر الجن قد استكثرتم من الإنس في إغوائهم، وقال أولياؤهم من الإنس: ربنا استمتع بعضنا ببعض، زيّنت لنا الشياطين الشهوات، وانتفعوا هم بطاعتنا، وبلغنا أجلنا الذي أجّلت لنا، كأنهم يعتذرون، فأصدر حكمه: النار مثواكم خالدين فيها إلا ما شاء الله، استثناء لبيان إرادته المطلقة، ويجوز أن يُراد به من كان منهم من أهل التوحيد دخلها بالفسق فيخرج بإيمانه، والله أعلم بمراده، إن ربك حكيم عليم.", "h": ["بيان سنة الله تعالى في الهداية والإضلال.", "بيان صعوبة وشدة ما يعاني الكافر إذا عُرض عليه الإيمان.", "القلوب الكافرة يُلقى فيها كل ما لا خير فيه من الشهوات والشبهات، وتكون مقراً للشيطان.", "فضيلة الذكر المنتج للتذكّر الذي هو الاتعاظ فالعمل.", "ثبوت التعاون بين أخباث الإنس والجن على الشر والفساد.", "إرادة الله مطلقة، يفعل ما يشاء ويحكم ما يريد، فلا يؤثّر فيها شيء."], "k": "«يشرح صدره للإسلام»… هل أطلب الهداية بصدق، وأستعد للموت قبل نزوله؟"}, {"lbl": "الآيات ١٢٩ – ١٣٢", "q": "وَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّـٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ ﴿١٢٩﴾ يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ ﴿١٣٠﴾ ذَٰلِكَ أَن لَّمۡ يَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا غَٰفِلُونَ ﴿١٣١﴾ وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ ﴿١٣٢﴾", "w": [["نولّي بعض الظالمين بعضاً", "نجعل بعضهم أولياء بعض بجامع كسبهم الشر والفساد."], ["بما كانوا يكسبون", "أي من الظلم والشر والفساد."], ["ألم يأتكم رسل منكم", "الاستفهام للتوبيخ، والرسل جمع رسول: من أوحى الله إليه شرعه وأمره بإبلاغه للناس، هذا من الإنس، أما من الجن فهم من يتلقّون عن الرسل من الإنس ويبلّغون إخوانهم من الجن، ويقال لهم النُّذُر."], ["يقصّون عليكم آياتي", "يخبرونكم بما فيها من الحجج متتبّعين ذلك، حتى لا يتركوا شيئاً إلا بلّغوكم إياه."], ["وينذرونكم لقاء يومكم", "يخوّفونكم بما في يومكم هذا، وهو يوم القيامة، من العذاب."], ["وأهلها غافلون", "لم تبلغهم دعوة تعرّفهم بربهم وطاعته وما لهم عليها من جزاء."]], "m": "وكذلك نولّي بعض الظالمين بعضاً بما كانوا يكسبون: سنة الله في أهل الظلم أن يجعل بعضهم أولياء بعض بالنصرة والمودة بسبب كسبهم السيئ، كموالاة شياطين الإنس للجن، فالجامع بينهم الخبث والشر، ويصح حمله على تسليط الظالمين بعضهم على بعض، وعلى إدخالهم النار فريقاً بعد فريق. ويوم القيامة ينادي الله الجن والإنس موبّخاً: ألم يأتكم رسل من جنسكم تفهمون عنهم، يقصّون عليكم آياتي وحججي لتعبدوني وحدي، وينذرونكم لقاء يومكم هذا وما فيه من جزاء؟ فقالوا: شهدنا على أنفسنا، وقد غرّتهم الحياة الدنيا فواصلوا الكفر والفسق، وشهدوا على أنفسهم أنهم كانوا كافرين. ذلك الإرسال لأن ربك لم يكن من شأنه ولا من مقتضى حكمته أن يُهلك القرى بظلم وأهلها غافلون، لم يؤمروا ولم يُنهوا ولم يعلموا بعاقبة الظلم. ولكل عامل من خير أو شر درجات مما عملوا: درجات في الجنة للصالح، ودركات في النار للسيئ، حسب علم الله بعمل كل عامل، وما ربك بغافل عما يعملون.", "h": ["بيان سنة الله تعالى في أن الأعمال هي سبب الموالاة بين الإنس والجن، فذو العمل الصالح يوالي أهل الصلاح، وذو العمل الفاسد يوالي أهل الفساد.", "التحذير من الاغترار بالحياة الدنيا.", "بيان العلة في إرسال الرسل، وهي إقامة الحجة على الناس، وعدم إهلاكهم قبل الإرسال إليهم.", "الأعمال بحسبها يتم الجزاء، فالصالحات تكسب الدرجات، والظلمات تكسب الدركات."], "k": "«وكذلك نولّي بعض الظالمين بعضاً»… من أصحابي الذين أواليهم، وعلى أي عمل يجتمع بيننا؟"}, {"lbl": "الآيات ١٣٣ – ١٣٥", "q": "وَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ ﴿١٣٣﴾ إِنَّ مَا تُوعَدُونَ لَأٓتٖۖ وَمَآ أَنتُم بِمُعۡجِزِينَ ﴿١٣٤﴾ قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَامِلٞۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ ﴿١٣٥﴾", "w": [["الغني", "عن كل ما سواه، فغناه تعالى ذاتي ليس بمكتسب كغنى غيره."], ["ذو الرحمة", "صاحب الرحمة العامة التي تشمل سائر مخلوقاته، والخاصة بالمؤمنين من عباده."], ["ويستخلف", "ينشئ خلقاً آخر يخلفون الناس في الدنيا."], ["إن ما توعدون لآت", "ما وعد الله به عباده من نعيم أو جحيم آتٍ لا محالة."], ["على مكانتكم", "على ما أنتم متمكّنون منه من حال صالحة أو فاسدة."], ["عاقبة الدار", "أي الدار الدنيا، وهي سعادة الآخرة القائمة على الإيمان والعمل الصالح."], ["إنه لا يفلح الظالمون", "لا يفوز الظالمون بالنجاة من النار ودخول الجنان، لأن ظلمهم يوبقهم في النار."]], "m": "بعد الدعوة إلى التوحيد وبيان جزاء من أقامه ومن ضيّعه، أخبر الله أنه الغني عن عباده، أمرهم بطاعته ونهاهم عن معصيته وليس في حاجة إليهم، بل هم الفقراء إليه، ذو الرحمة. وليعلم العادلون بربهم أنه قادر على إذهابهم بالمرة والإتيان بقوم آخرين أطوع لله منهم: إن يشأ يذهبكم ويستخلف من بعدكم ما يشاء كما أنشأكم من ذرية قوم آخرين، وأن ما يوعدونه من البعث والحساب والجزاء آتٍ لا محالة، وما أنتم بمعجزين ولا فائتين، فسوف يجزي كلاً بعمله. ثم أمر رسوله أن يقول لكفار قريش: اعملوا على مكانتكم ما دمتم مصرّين على الكفر، إني عامل على مكانتي، فسوف تعلمون من تكون له عاقبة الدار، وهي الجنة دار السلام، أنا أم أنتم؟ إنه لا يفلح الظالمون بالنجاة من النار ودخول الجنان، ولا شك أنكم أنتم الظالمون بكفركم.", "h": ["تقرير غنى الله تعالى المطلق عن سائر خلقه.", "بيان قدرة الله تعالى على إذهاب الخلق كلهم والإتيان بآخرين غيرهم.", "صدق وعد الله تعالى وعدم تخلّفه.", "تهديد المشركين بالعذاب إن هم أصرّوا على الشرك والكفر، والذي دلّ عليه قوله: «اعملوا على مكانتكم إني عامل فسوف تعلمون من تكون له عاقبة الدار، إنه لا يفلح الظالمون»."], "k": "«وربك الغني ذو الرحمة»… ربي غني عن عبادتي وأنا الفقير إليها؛ فلمن أعمل حين أعمل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 96;
insert into public.tdb_cards(topic, i, body) select 96, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢٢ – ١٢٤", "q": "أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورٗا يَمۡشِي بِهِۦ فِي ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِي ٱلظُّلُمَٰتِ لَيۡسَ بِخَارِجٖ مِّنۡهَاۚ كَذَٰلِكَ زُيِّنَ لِلۡكَٰفِرِينَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٢٢﴾ وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ ﴿١٢٣﴾ وَإِذَا جَآءَتۡهُمۡ ءَايَةٞ قَالُواْ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَآ أُوتِيَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ سَيُصِيبُ ٱلَّذِينَ أَجۡرَمُواْ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٞ شَدِيدُۢ بِمَا كَانُواْ يَمۡكُرُونَ ﴿١٢٤﴾", "w": [["ميتاً", "الميت فاقد الروح، والمراد روح الإيمان."], ["أحييناه", "جعلناه حياً بروح الإيمان."], ["مثله", "صفته ونعته: امرؤ في الظلمات ليس بخارج منها."], ["قرية", "مدينة كبيرة."], ["ليمكروا فيها", "بفعل المنكرات والدعوة إلى ارتكابها بأسلوب الخديعة والاحتيال."], ["وما يمكرون إلا بأنفسهم", "لأن عاقبة المكر تعود على الماكر نفسه، لآية «ولا يحيق المكر السيئ إلا بأهله»."], ["وإذا جاءتهم آية", "أي من القرآن الكريم تدعوهم إلى الحق."], ["صغار", "الذل والهوان."]], "m": "ما زال السياق في حرب العادلين بربهم الذين يزيّن لهم الشيطان تحريم ما أحل الله وتحليل ما حرّم: أوَمن كان ميتاً بالشرك والكفر فأحييناه بالإيمان والتوحيد وجعلنا له نوراً يمشي به في الناس، وهو عمر بن الخطاب أو عمار بن ياسر، كمن مثله في ظلمات الشرك والكفر والمعاصي ليس بخارج منها، وهو أبو جهل؟ لا يستويان، فكيف أطاع المشركون أبا جهل وعصوا عمر؟ لأن الكافرين لظلمة نفوسهم واتباع أهوائهم زُيّن لهم عملهم الباطل، على سنة الله في أن من أحب شيئاً وغالى في حبه على غير هدى أصبح في نظره زيناً وهو شين. وكذلك جعلنا في كل قرية أكابر مجرميها ليمكروا فيها، يفسدون عقائد الناس وأخلاقهم بزخرف القول والخداع، وما يمكرون إلا بأنفسهم إذ ستحل بهم العقوبة، وما يشعرون. وإذا جاءتهم آية من القرآن تدعوهم إلى تصديق الرسول قالوا: لن نؤمن حتى نؤتى مثل ما أوتي رسل الله من المعجزات كعصا موسى، فردّ الله عليهم هذا العلو والتكبر: الله أعلم حيث يجعل رسالته، يجعلها في القلوب المشرقة والنفوس الزكية لا في القلوب المظلمة والنفوس الخبيثة. سيصيب الذين أجرموا صغار عند الله يوم يلقونه، وعذاب شديد بما كانوا يمكرون بالناس بتضليلهم وإفساد قلوبهم.", "h": ["الإيمان حياة والكفر موت، المؤمن يعيش في نور والكافر في ظلمات.", "بيان سنة الله تعالى في تزيين الأعمال القبيحة.", "قلّما تخلو مدينة من مجرمين يمكرون فيها.", "عاقبة المكر عائدة على الماكر نفسه.", "بيان تعنّت المشركين في مكة على عهد نزول القرآن.", "الرسالة توهب لا تكتسب.", "بيان عقوبة أهل الإجرام في الأرض."], "k": "«وجعلنا له نوراً يمشي به في الناس»… هل يرى الناس في مشيي بينهم أثر نور الإيمان؟"}, {"lbl": "الآيات ١٢٥ – ١٢٨", "q": "فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ ﴿١٢٥﴾ وَهَٰذَا صِرَٰطُ رَبِّكَ مُسۡتَقِيمٗاۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَذَّكَّرُونَ ﴿١٢٦﴾ ۞لَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٢٧﴾ وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا يَٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِيَآؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٖ وَبَلَغۡنَآ أَجَلَنَا ٱلَّذِيٓ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ ﴿١٢٨﴾", "w": [["شرح صدره", "توسعته لقبول الحق وحمل الوارد عليه من أنوار الإيمان، وعلامة ذلك: الإنابة إلى دار الخلود، والتجافي عن دار الغرور، والاستعداد للموت قبل نزوله."], ["حرجاً", "ضيقاً لا يتسع لقبول الحق ولا لنور الإيمان."], ["كأنما يصّعّد", "يصعب عليه قبول الإيمان حتى كأنه يتكلّف الصعود إلى السماء."], ["الرجس", "النجس وما لا خير فيه كالشيطان."], ["فصّلنا الآيات", "بيّناها وأوضحناها غاية البيان والتوضيح."], ["يذّكرون", "يتذكّرون فيتّعظون."], ["دار السلام", "الجنة، والسلام اسم من أسماء الله تعالى، فهي مضافة إلى الله."], ["استكثرتم", "أي من إضلال الإنس وإغوائهم."], ["استمتع بعضنا ببعض", "انتفع كل منا بصاحبه، أي تبادلنا المنافع بيننا حتى الموت."], ["أجلنا الذي أجّلت لنا", "الوقت الذي وقّت لنا، وهو أجل موتنا فمتنا."], ["مثواكم", "مأواكم ومقرّ بقائكم وإقامتكم."], ["حكيم عليم", "حكيم في وضع كل شيء في موضعه، فلا يخلّد أهل الإيمان في النار ولا يُخرج أهل الكفر منها، عليم بأهل الإيمان وأهل الكفر."]], "m": "بعد ذلك البيان لطريق الهداية، أعلم الله عباده أن الهداية والإضلال بيده، يهدي من يشاء برحمته ويضل من يشاء بعدله، ولكلٍّ منهما سنن: فمن طلب الهداية صادقاً علم الله ذلك منه فسهّل له طرقها، ومن ذلك أنه يشرح صدره لقبول الإيمان وأنواره فيكمل ويسعد، ومن طلب الغواية صادقاً هيّأ له أسبابها، فجعل صدره ضيقاً حرجاً لا يتسع لقبول الإيمان، كأنما يتكلّف الصعود إلى السماء وما هو بقادر. كذلك يجعل الله الرجس، كل ما لا خير فيه من الكبر والحسد والشرك والشيطان، على الذين لا يؤمنون، لقبول المحل له نتيجة خلوّه من الإيمان. وهذا صراط ربك مستقيماً فالزمه، فإنه يفضي بك إلى كرامة ربك وجواره، قد فصّلنا الآيات لقوم يذّكرون فيؤمنون ويعملون، لهم دار السلام عند ربهم، وهو وليهم بالنصر في الدنيا والإنعام في الآخرة بما كانوا يعملون. ويوم يحشرهم جميعاً إنسهم وجنهم: يا معشر الجن قد استكثرتم من الإنس في إغوائهم، وقال أولياؤهم من الإنس: ربنا استمتع بعضنا ببعض، زيّنت لنا الشياطين الشهوات، وانتفعوا هم بطاعتنا، وبلغنا أجلنا الذي أجّلت لنا، كأنهم يعتذرون، فأصدر حكمه: النار مثواكم خالدين فيها إلا ما شاء الله، استثناء لبيان إرادته المطلقة، ويجوز أن يُراد به من كان منهم من أهل التوحيد دخلها بالفسق فيخرج بإيمانه، والله أعلم بمراده، إن ربك حكيم عليم.", "h": ["بيان سنة الله تعالى في الهداية والإضلال.", "بيان صعوبة وشدة ما يعاني الكافر إذا عُرض عليه الإيمان.", "القلوب الكافرة يُلقى فيها كل ما لا خير فيه من الشهوات والشبهات، وتكون مقراً للشيطان.", "فضيلة الذكر المنتج للتذكّر الذي هو الاتعاظ فالعمل.", "ثبوت التعاون بين أخباث الإنس والجن على الشر والفساد.", "إرادة الله مطلقة، يفعل ما يشاء ويحكم ما يريد، فلا يؤثّر فيها شيء."], "k": "«يشرح صدره للإسلام»… هل أطلب الهداية بصدق، وأستعد للموت قبل نزوله؟"}, {"lbl": "الآيات ١٢٩ – ١٣٢", "q": "وَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّـٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ ﴿١٢٩﴾ يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ ﴿١٣٠﴾ ذَٰلِكَ أَن لَّمۡ يَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا غَٰفِلُونَ ﴿١٣١﴾ وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ ﴿١٣٢﴾", "w": [["نولّي بعض الظالمين بعضاً", "نجعل بعضهم أولياء بعض بجامع كسبهم الشر والفساد."], ["بما كانوا يكسبون", "أي من الظلم والشر والفساد."], ["ألم يأتكم رسل منكم", "الاستفهام للتوبيخ، والرسل جمع رسول: من أوحى الله إليه شرعه وأمره بإبلاغه للناس، هذا من الإنس، أما من الجن فهم من يتلقّون عن الرسل من الإنس ويبلّغون إخوانهم من الجن، ويقال لهم النُّذُر."], ["يقصّون عليكم آياتي", "يخبرونكم بما فيها من الحجج متتبّعين ذلك، حتى لا يتركوا شيئاً إلا بلّغوكم إياه."], ["وينذرونكم لقاء يومكم", "يخوّفونكم بما في يومكم هذا، وهو يوم القيامة، من العذاب."], ["وأهلها غافلون", "لم تبلغهم دعوة تعرّفهم بربهم وطاعته وما لهم عليها من جزاء."]], "m": "وكذلك نولّي بعض الظالمين بعضاً بما كانوا يكسبون: سنة الله في أهل الظلم أن يجعل بعضهم أولياء بعض بالنصرة والمودة بسبب كسبهم السيئ، كموالاة شياطين الإنس للجن، فالجامع بينهم الخبث والشر، ويصح حمله على تسليط الظالمين بعضهم على بعض، وعلى إدخالهم النار فريقاً بعد فريق. ويوم القيامة ينادي الله الجن والإنس موبّخاً: ألم يأتكم رسل من جنسكم تفهمون عنهم، يقصّون عليكم آياتي وحججي لتعبدوني وحدي، وينذرونكم لقاء يومكم هذا وما فيه من جزاء؟ فقالوا: شهدنا على أنفسنا، وقد غرّتهم الحياة الدنيا فواصلوا الكفر والفسق، وشهدوا على أنفسهم أنهم كانوا كافرين. ذلك الإرسال لأن ربك لم يكن من شأنه ولا من مقتضى حكمته أن يُهلك القرى بظلم وأهلها غافلون، لم يؤمروا ولم يُنهوا ولم يعلموا بعاقبة الظلم. ولكل عامل من خير أو شر درجات مما عملوا: درجات في الجنة للصالح، ودركات في النار للسيئ، حسب علم الله بعمل كل عامل، وما ربك بغافل عما يعملون.", "h": ["بيان سنة الله تعالى في أن الأعمال هي سبب الموالاة بين الإنس والجن، فذو العمل الصالح يوالي أهل الصلاح، وذو العمل الفاسد يوالي أهل الفساد.", "التحذير من الاغترار بالحياة الدنيا.", "بيان العلة في إرسال الرسل، وهي إقامة الحجة على الناس، وعدم إهلاكهم قبل الإرسال إليهم.", "الأعمال بحسبها يتم الجزاء، فالصالحات تكسب الدرجات، والظلمات تكسب الدركات."], "k": "«وكذلك نولّي بعض الظالمين بعضاً»… من أصحابي الذين أواليهم، وعلى أي عمل يجتمع بيننا؟"}, {"lbl": "الآيات ١٣٣ – ١٣٥", "q": "وَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ ﴿١٣٣﴾ إِنَّ مَا تُوعَدُونَ لَأٓتٖۖ وَمَآ أَنتُم بِمُعۡجِزِينَ ﴿١٣٤﴾ قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَامِلٞۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ ﴿١٣٥﴾", "w": [["الغني", "عن كل ما سواه، فغناه تعالى ذاتي ليس بمكتسب كغنى غيره."], ["ذو الرحمة", "صاحب الرحمة العامة التي تشمل سائر مخلوقاته، والخاصة بالمؤمنين من عباده."], ["ويستخلف", "ينشئ خلقاً آخر يخلفون الناس في الدنيا."], ["إن ما توعدون لآت", "ما وعد الله به عباده من نعيم أو جحيم آتٍ لا محالة."], ["على مكانتكم", "على ما أنتم متمكّنون منه من حال صالحة أو فاسدة."], ["عاقبة الدار", "أي الدار الدنيا، وهي سعادة الآخرة القائمة على الإيمان والعمل الصالح."], ["إنه لا يفلح الظالمون", "لا يفوز الظالمون بالنجاة من النار ودخول الجنان، لأن ظلمهم يوبقهم في النار."]], "m": "بعد الدعوة إلى التوحيد وبيان جزاء من أقامه ومن ضيّعه، أخبر الله أنه الغني عن عباده، أمرهم بطاعته ونهاهم عن معصيته وليس في حاجة إليهم، بل هم الفقراء إليه، ذو الرحمة. وليعلم العادلون بربهم أنه قادر على إذهابهم بالمرة والإتيان بقوم آخرين أطوع لله منهم: إن يشأ يذهبكم ويستخلف من بعدكم ما يشاء كما أنشأكم من ذرية قوم آخرين، وأن ما يوعدونه من البعث والحساب والجزاء آتٍ لا محالة، وما أنتم بمعجزين ولا فائتين، فسوف يجزي كلاً بعمله. ثم أمر رسوله أن يقول لكفار قريش: اعملوا على مكانتكم ما دمتم مصرّين على الكفر، إني عامل على مكانتي، فسوف تعلمون من تكون له عاقبة الدار، وهي الجنة دار السلام، أنا أم أنتم؟ إنه لا يفلح الظالمون بالنجاة من النار ودخول الجنان، ولا شك أنكم أنتم الظالمون بكفركم.", "h": ["تقرير غنى الله تعالى المطلق عن سائر خلقه.", "بيان قدرة الله تعالى على إذهاب الخلق كلهم والإتيان بآخرين غيرهم.", "صدق وعد الله تعالى وعدم تخلّفه.", "تهديد المشركين بالعذاب إن هم أصرّوا على الشرك والكفر، والذي دلّ عليه قوله: «اعملوا على مكانتكم إني عامل فسوف تعلمون من تكون له عاقبة الدار، إنه لا يفلح الظالمون»."], "k": "«وربك الغني ذو الرحمة»… ربي غني عن عبادتي وأنا الفقير إليها؛ فلمن أعمل حين أعمل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (97, 6, 136, 144, 'سورة الأنعام ١٣٦ – ١٤٤', 'تشريعات الجاهلية في الحرث والأنعام، و«وآتوا حقه يوم حصاده»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 97) = $j$[{"lbl": "الآيات ١٣٦ – ١٤٠", "q": "وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَٰمِ نَصِيبٗا فَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ ﴿١٣٦﴾ وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ ﴿١٣٧﴾ وَقَالُواْ هَٰذِهِۦٓ أَنۡعَٰمٞ وَحَرۡثٌ حِجۡرٞ لَّا يَطۡعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعۡمِهِمۡ وَأَنۡعَٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَٰمٞ لَّا يَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَيۡهَا ٱفۡتِرَآءً عَلَيۡهِۚ سَيَجۡزِيهِم بِمَا كَانُواْ يَفۡتَرُونَ ﴿١٣٨﴾ وَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ﴿١٣٩﴾ قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ ﴿١٤٠﴾", "w": [["مما ذرأ", "مما خلق."], ["من الحرث والأنعام", "الحرث: كل ما يُحرث له الأرض من الزروع، والأنعام: الإبل والبقر والغنم."], ["نصيباً", "حظاً وقدراً معيّناً."], ["لشركائنا", "شركاؤهم: أوثانهم التي أشركوها في عبادة الخالق عز وجل."], ["ساء ما يحكمون", "قبُح حكمهم في ذلك، إذ آثروا أوثانهم على الله."], ["ليُردوهم", "اللام لام العاقبة، ومعنى يردوهم: يُهلكوهم."], ["وليلبسوا", "ليخلطوا عليهم دينهم."], ["حِجر", "ممنوعة على غير من لم يأذنوا له في أكلها."], ["حُرّمت ظهورها", "لا يركبونها ولا يحملون عليها."], ["افتراء على الله", "كذباً على الله عز وجل."], ["على أزواجنا", "أي إناثنا."], ["وإن يكن ميتة", "إن ولد ما في بطن الحيوان ميتاً فهم فيه شركاء، الذكور والإناث سواء."], ["سفهاً بغير علم", "حمقاً وطيشاً وعدم رشد، وذلك لجهلهم."]], "m": "ما زال السياق في التنديد بما كان المشركون يبتدعونه ويشرّعونه بلا علم ولا هدى: جعلوا لله مما خلق من الحرث والأنعام نصيباً، وللآلهة نصيباً، فقالوا: هذا لله بزعمهم، وما شرعه لهم، وهذا لشركائنا، فإذا أنبت ما جعلوه لله ولم ينبت ما للشركاء حوّلوه إلى الشركاء بدعوى أنها فقيرة والله غني، وإذا حصل العكس لم يحوّلوا ما للآلهة إلى الله، ساء ما يحكمون، تحيّز ممقوت وتحكّم فاسد. وكذلك زيّن لكثير من المشركين شركاؤهم من شياطين الجن والإنس قتل أولادهم، كوأد البنات خوف العار، وقتل الأولاد خوف الفقر أو نذرهم للآلهة، ليُهلكوهم ويخلطوا عليهم دينهم بالشرك، ولو شاء الله ما فعلوه، فذرهم وما يفترون. وقالوا: هذه أنعام وحرث حِجر لا يطعمها إلا من نشاء بزعمهم، وأنعام حُرّمت ظهورها كالسائبة والحام، وأنعام لا يذكرون اسم الله عليها فلا يحجّون عليها، افتراء على الله، سيجزيهم بما كانوا يفترون. وقالوا: ما في بطون هذه الأنعام خالصة لذكورنا ومحرّم على إناثنا، فلا يشرب النساء ألبانها ولا يأكلن لحوم أجنّتها، إلا أن يولد الجنين ميتاً فيحل للنساء والرجال معاً، سيجزيهم وصفهم إنه حكيم عليم. قد خسر الذين قتلوا أولادهم سفهاً بغير علم، وحرّموا ما رزقهم الله افتراء على الله، قد ضلّوا وما كانوا مهتدين.", "h": ["حرمة الابتداع في الدين، والتشريع المنافي لشرع الله تعالى، وإن لم يُنسب إلى الله تعالى.", "ما ينذره الجهال اليوم من نذور للأولياء، وإعطائهم شيئاً من الأنعام والحرث والشجر، هو من عمل المشركين، زيّنه الشيطان لجهال المسلمين.", "حرمة قتل النفس لأي سبب كان، وتحديد النسل اليوم وإلزام الأمة به من الحكام من عمل أهل الجاهلية الذين قتلوا أولادهم سفهاً بغير علم، كقتل البنات خشية العار، والأولاد خشية الفقر."], "k": "«وحرّموا ما رزقهم الله افتراء على الله»… هل أحرّم أو أحلّل شيئاً بهوى أو عادة، لا بعلم من الله ورسوله؟"}, {"lbl": "الآيات ١٤١ – ١٤٤", "q": "۞وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّـٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ مُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ﴿١٤١﴾ وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةٗ وَفَرۡشٗاۚ كُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ﴿١٤٢﴾ ثَمَٰنِيَةَ أَزۡوَٰجٖۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَيۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ نَبِّـُٔونِي بِعِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٤٣﴾ وَمِنَ ٱلۡإِبِلِ ٱثۡنَيۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٤٤﴾", "w": [["أنشأ جنات", "خلق جنات، جمع جنة وهي البستان."], ["معروشات", "ما يُعمل له العريش من العنب، وما لا يُعرش له من سائر الأشجار."], ["مختلفاً أُكُله", "ثمره الذي يؤكل منه."], ["متشابهاً", "في الورق، وغير متشابه في الحب والطعم."], ["حقه", "ما وجب فيه من الزكاة."], ["يوم حصاده", "يوم حصاده إن كان حباً، وجذاذه إن كان نخلاً."], ["ولا تسرفوا في إخراجه", "بأن لا تُبقوا لعيالكم منه شيئاً."], ["حمولة", "ما يُحمل عليها من الإبل."], ["وفرشاً", "الفرش: الصغار من الحيوان."], ["خطوات الشيطان", "مسالكه في التحريم والتحليل للإضلال والغواية."], ["أم ما اشتملت عليه أرحام الأنثيين", "أنثى الضأن وأنثى الماعز، ذكراً كان أو أنثى."], ["نبّئوني بعلم", "أخبروني بأيّها حرّم، بعلم صحيح لا بوسواس الشياطين."], ["أم كنتم شهداء", "حاضرين وقت تحريمه تعالى ذلك عليكم إن كان قد حرّمه."]], "m": "لما توعّد الله المفترين عليه بالتحريم والتحليل، ذكر مظاهر قدرته وعلمه وحكمته في إبطال تحريمهم: وهو الذي أنشأ جنات معروشات يُحمل شجرها على العروش كالعنب، وغير معروشات، والنخل والزرع مختلفاً ثمره وطعمه، والزيتون والرمان متشابهاً في الورق وغير متشابه في الحب والطعم، وأذن في أكله: كلوا من ثمره إذا أثمر، وأمر بإخراج الواجب فيه، وهو الزكاة: وآتوا حقه يوم حصاده، أي بعد درسه وتصفيته، ونهى عن الإسراف في إخراجها غلواً حتى لا يبقى لمن يعولون ما يكفيهم: ولا تسرفوا إنه لا يحب المسرفين. وأنشأ من الأنعام حمولة كباراً يُحمل عليها، وفرشاً صغاراً، كلوا مما رزقكم الله، ولا تتبعوا خطوات الشيطان في تحريم ما أحل الله، إنه لكم عدو مبين. وأنشأ ثمانية أزواج: من الضأن الكبش والنعجة، ومن المعز التيس والعنزة، ومن الإبل الناقة والجمل، ومن البقر الثور والبقرة، وأمر رسوله أن يحاجّهم: آلذكرين حرّم أم الأنثيين أم ما اشتملت عليه أرحام الأنثيين؟ فإن قلتم الذكرين فكل الذكور حرام، أو الأنثيين فكل الإناث حرام، أو ما في الأرحام فكل مولود حرام، فبأي علم حرّمتم البعض وحلّلتم البعض؟ فالله لم يحرّم من هذه الأزواج الثمانية شيئاً، وإنما حرّم الميتة وما لم يُذكر اسم الله عليه. أم كنتم شهداء إذ وصّاكم الله بهذا؟ تبكيت لهم، إنما هو الافتراء. فمن أظلم ممن افترى على الله كذباً ليضل الناس بغير علم؟ إن الله لا يهدي القوم الظالمين.", "h": ["إباحة أكل التمر والعنب والرمان والزيتون.", "وجوب الزكاة في الزيتون والتمر والحبوب إذا بلغت النصاب، وهو خمسة أوسق، والوسق ستون صاعاً، والصاع أربع حفنات.", "جواز الأكل من الثمر قبل جذاذه وإخراج الزكاة منه.", "حرمة الإسراف في المال، بأن ينفقه فيما لا يعني، أو ينفقه كله ولم يترك لأهله شيئاً.", "إباحة أكل بهيمة الأنعام، وهي ثمانية أزواج: ضأن وماعز، وإبل وبقر، وكلها ذكر وأنثى.", "إبطال تشريع الجاهلية في التحريم والتحليل، فالحلال ما أحلّه الله ورسوله، والحرام ما حرّمه الله ورسوله.", "جواز الجدال والحجاج لإحقاق الحق أو إبطال الباطل.", "لا أظلم ممن يكذب على الله تعالى فيشرّع لعباده ما لم يشرّع لهم."], "k": "«وآتوا حقه يوم حصاده»… حين يأتيني رزق، هل أتذكّر حق الله فيه قبل أن أتمتّع به؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 97;
insert into public.tdb_cards(topic, i, body) select 97, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٣٦ – ١٤٠", "q": "وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَٰمِ نَصِيبٗا فَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ ﴿١٣٦﴾ وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ ﴿١٣٧﴾ وَقَالُواْ هَٰذِهِۦٓ أَنۡعَٰمٞ وَحَرۡثٌ حِجۡرٞ لَّا يَطۡعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعۡمِهِمۡ وَأَنۡعَٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَٰمٞ لَّا يَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَيۡهَا ٱفۡتِرَآءً عَلَيۡهِۚ سَيَجۡزِيهِم بِمَا كَانُواْ يَفۡتَرُونَ ﴿١٣٨﴾ وَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ﴿١٣٩﴾ قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ ﴿١٤٠﴾", "w": [["مما ذرأ", "مما خلق."], ["من الحرث والأنعام", "الحرث: كل ما يُحرث له الأرض من الزروع، والأنعام: الإبل والبقر والغنم."], ["نصيباً", "حظاً وقدراً معيّناً."], ["لشركائنا", "شركاؤهم: أوثانهم التي أشركوها في عبادة الخالق عز وجل."], ["ساء ما يحكمون", "قبُح حكمهم في ذلك، إذ آثروا أوثانهم على الله."], ["ليُردوهم", "اللام لام العاقبة، ومعنى يردوهم: يُهلكوهم."], ["وليلبسوا", "ليخلطوا عليهم دينهم."], ["حِجر", "ممنوعة على غير من لم يأذنوا له في أكلها."], ["حُرّمت ظهورها", "لا يركبونها ولا يحملون عليها."], ["افتراء على الله", "كذباً على الله عز وجل."], ["على أزواجنا", "أي إناثنا."], ["وإن يكن ميتة", "إن ولد ما في بطن الحيوان ميتاً فهم فيه شركاء، الذكور والإناث سواء."], ["سفهاً بغير علم", "حمقاً وطيشاً وعدم رشد، وذلك لجهلهم."]], "m": "ما زال السياق في التنديد بما كان المشركون يبتدعونه ويشرّعونه بلا علم ولا هدى: جعلوا لله مما خلق من الحرث والأنعام نصيباً، وللآلهة نصيباً، فقالوا: هذا لله بزعمهم، وما شرعه لهم، وهذا لشركائنا، فإذا أنبت ما جعلوه لله ولم ينبت ما للشركاء حوّلوه إلى الشركاء بدعوى أنها فقيرة والله غني، وإذا حصل العكس لم يحوّلوا ما للآلهة إلى الله، ساء ما يحكمون، تحيّز ممقوت وتحكّم فاسد. وكذلك زيّن لكثير من المشركين شركاؤهم من شياطين الجن والإنس قتل أولادهم، كوأد البنات خوف العار، وقتل الأولاد خوف الفقر أو نذرهم للآلهة، ليُهلكوهم ويخلطوا عليهم دينهم بالشرك، ولو شاء الله ما فعلوه، فذرهم وما يفترون. وقالوا: هذه أنعام وحرث حِجر لا يطعمها إلا من نشاء بزعمهم، وأنعام حُرّمت ظهورها كالسائبة والحام، وأنعام لا يذكرون اسم الله عليها فلا يحجّون عليها، افتراء على الله، سيجزيهم بما كانوا يفترون. وقالوا: ما في بطون هذه الأنعام خالصة لذكورنا ومحرّم على إناثنا، فلا يشرب النساء ألبانها ولا يأكلن لحوم أجنّتها، إلا أن يولد الجنين ميتاً فيحل للنساء والرجال معاً، سيجزيهم وصفهم إنه حكيم عليم. قد خسر الذين قتلوا أولادهم سفهاً بغير علم، وحرّموا ما رزقهم الله افتراء على الله، قد ضلّوا وما كانوا مهتدين.", "h": ["حرمة الابتداع في الدين، والتشريع المنافي لشرع الله تعالى، وإن لم يُنسب إلى الله تعالى.", "ما ينذره الجهال اليوم من نذور للأولياء، وإعطائهم شيئاً من الأنعام والحرث والشجر، هو من عمل المشركين، زيّنه الشيطان لجهال المسلمين.", "حرمة قتل النفس لأي سبب كان، وتحديد النسل اليوم وإلزام الأمة به من الحكام من عمل أهل الجاهلية الذين قتلوا أولادهم سفهاً بغير علم، كقتل البنات خشية العار، والأولاد خشية الفقر."], "k": "«وحرّموا ما رزقهم الله افتراء على الله»… هل أحرّم أو أحلّل شيئاً بهوى أو عادة، لا بعلم من الله ورسوله؟"}, {"lbl": "الآيات ١٤١ – ١٤٤", "q": "۞وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّـٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ مُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ﴿١٤١﴾ وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةٗ وَفَرۡشٗاۚ كُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ﴿١٤٢﴾ ثَمَٰنِيَةَ أَزۡوَٰجٖۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَيۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ نَبِّـُٔونِي بِعِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٤٣﴾ وَمِنَ ٱلۡإِبِلِ ٱثۡنَيۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٤٤﴾", "w": [["أنشأ جنات", "خلق جنات، جمع جنة وهي البستان."], ["معروشات", "ما يُعمل له العريش من العنب، وما لا يُعرش له من سائر الأشجار."], ["مختلفاً أُكُله", "ثمره الذي يؤكل منه."], ["متشابهاً", "في الورق، وغير متشابه في الحب والطعم."], ["حقه", "ما وجب فيه من الزكاة."], ["يوم حصاده", "يوم حصاده إن كان حباً، وجذاذه إن كان نخلاً."], ["ولا تسرفوا في إخراجه", "بأن لا تُبقوا لعيالكم منه شيئاً."], ["حمولة", "ما يُحمل عليها من الإبل."], ["وفرشاً", "الفرش: الصغار من الحيوان."], ["خطوات الشيطان", "مسالكه في التحريم والتحليل للإضلال والغواية."], ["أم ما اشتملت عليه أرحام الأنثيين", "أنثى الضأن وأنثى الماعز، ذكراً كان أو أنثى."], ["نبّئوني بعلم", "أخبروني بأيّها حرّم، بعلم صحيح لا بوسواس الشياطين."], ["أم كنتم شهداء", "حاضرين وقت تحريمه تعالى ذلك عليكم إن كان قد حرّمه."]], "m": "لما توعّد الله المفترين عليه بالتحريم والتحليل، ذكر مظاهر قدرته وعلمه وحكمته في إبطال تحريمهم: وهو الذي أنشأ جنات معروشات يُحمل شجرها على العروش كالعنب، وغير معروشات، والنخل والزرع مختلفاً ثمره وطعمه، والزيتون والرمان متشابهاً في الورق وغير متشابه في الحب والطعم، وأذن في أكله: كلوا من ثمره إذا أثمر، وأمر بإخراج الواجب فيه، وهو الزكاة: وآتوا حقه يوم حصاده، أي بعد درسه وتصفيته، ونهى عن الإسراف في إخراجها غلواً حتى لا يبقى لمن يعولون ما يكفيهم: ولا تسرفوا إنه لا يحب المسرفين. وأنشأ من الأنعام حمولة كباراً يُحمل عليها، وفرشاً صغاراً، كلوا مما رزقكم الله، ولا تتبعوا خطوات الشيطان في تحريم ما أحل الله، إنه لكم عدو مبين. وأنشأ ثمانية أزواج: من الضأن الكبش والنعجة، ومن المعز التيس والعنزة، ومن الإبل الناقة والجمل، ومن البقر الثور والبقرة، وأمر رسوله أن يحاجّهم: آلذكرين حرّم أم الأنثيين أم ما اشتملت عليه أرحام الأنثيين؟ فإن قلتم الذكرين فكل الذكور حرام، أو الأنثيين فكل الإناث حرام، أو ما في الأرحام فكل مولود حرام، فبأي علم حرّمتم البعض وحلّلتم البعض؟ فالله لم يحرّم من هذه الأزواج الثمانية شيئاً، وإنما حرّم الميتة وما لم يُذكر اسم الله عليه. أم كنتم شهداء إذ وصّاكم الله بهذا؟ تبكيت لهم، إنما هو الافتراء. فمن أظلم ممن افترى على الله كذباً ليضل الناس بغير علم؟ إن الله لا يهدي القوم الظالمين.", "h": ["إباحة أكل التمر والعنب والرمان والزيتون.", "وجوب الزكاة في الزيتون والتمر والحبوب إذا بلغت النصاب، وهو خمسة أوسق، والوسق ستون صاعاً، والصاع أربع حفنات.", "جواز الأكل من الثمر قبل جذاذه وإخراج الزكاة منه.", "حرمة الإسراف في المال، بأن ينفقه فيما لا يعني، أو ينفقه كله ولم يترك لأهله شيئاً.", "إباحة أكل بهيمة الأنعام، وهي ثمانية أزواج: ضأن وماعز، وإبل وبقر، وكلها ذكر وأنثى.", "إبطال تشريع الجاهلية في التحريم والتحليل، فالحلال ما أحلّه الله ورسوله، والحرام ما حرّمه الله ورسوله.", "جواز الجدال والحجاج لإحقاق الحق أو إبطال الباطل.", "لا أظلم ممن يكذب على الله تعالى فيشرّع لعباده ما لم يشرّع لهم."], "k": "«وآتوا حقه يوم حصاده»… حين يأتيني رزق، هل أتذكّر حق الله فيه قبل أن أتمتّع به؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (98, 6, 145, 153, 'سورة الأنعام ١٤٥ – ١٥٣', '«قل لا أجد فيما أوحي إليّ محرّماً»، و«قل تعالوا أتلُ ما حرّم ربكم عليكم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 98) = $j$[{"lbl": "الآيات ١٤٥ – ١٤٧", "q": "قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ رَبَّكَ غَفُورٞ رَّحِيمٞ ﴿١٤٥﴾ وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ ﴿١٤٦﴾ فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةٖ وَٰسِعَةٖ وَلَا يُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ ﴿١٤٧﴾", "w": [["محرّماً على طاعم يطعمه", "محظوراً ممنوعاً على آكل يأكله."], ["ميتة أو دماً مسفوحاً", "الميتة: ما مات دون تذكية، والدم المسفوح: المصبوب صباً، لا المختلط باللحم والعظام."], ["رجس", "نجس وقذر قبيح حرام."], ["أو فسقاً أُهلّ لغير الله به", "الفسق: الخروج عن طاعة الله، والمراد ما ذُبح ولم يُذكر اسم الله عليه، وإنما ذُكر عليه اسم الأصنام أو غيرها."], ["فمن اضطر غير باغ ولا عاد", "اضطُرّ: ألجأته الضرورة وهي خوف الهلاك، والباغي: الظالم، والعادي: المعتدي المجاوز للحد."], ["هادوا", "اليهود."], ["ذي ظفر", "صاحب ظفر، وهو الحيوان الذي لا يفرّق أصابعه كالإبل."], ["ما حملت ظهورهما أو الحوايا", "الشحم العالق بالظهر، والحوايا: المباعر والمصارين."], ["أو ما اختلط بعظم", "عُفي لهم عن الشحم المختلط بالعظم، كما عُفي عن الحوايا والعالق بالظهر."], ["ببغيهم", "بسبب ظلمهم."], ["ولا يُردّ بأسه", "بطشه وعذابه."]], "m": "ما زال السياق في الحجاج مع المحرّمين ما لم يحرّم الله، فأمر رسوله أن يقول: لا أجد فيما أوحي إليّ وأنا رسول الله شيئاً محرّماً على آكل يأكله إلا أن يكون ميتة لم تُذكَّ الذكاة الشرعية، أو دماً مصبوباً لا المختلط بالعظم واللحم كالكبد والطحال، أو لحم خنزير فإنه نجس قذر حرام، أو فسقاً ذُبح ولم يُذكر اسم الله عليه أو ذُكر عليه اسم الأصنام. فمن اضطُرّ غير باغ يأكلها تلذّذاً لا دفعاً للموت، ولا عاد متجاوز القدر الذي يدفع به الموت، فإن ربك غفور رحيم، ومن مغفرته ورحمته أنه أذن للمضطر بأكل الحرام في الضرورة. ثم أخبر أنه حرّم على اليهود كل ذي ظفر، ما ليس له أصابع مفرّقة كالإبل والنعام والبط والإوز، ومن البقر والغنم حرّم عليهم شحومهما اللاصقة بالكرش والكلى، إلا ما حملت ظهورهما أو الحوايا أو ما اختلط بعظم، ذلك جزيناهم ببغيهم، وإنا لصادقون فيما أخبرنا به عنهم، وهم الكاذبون إذ قالوا: إنما حرّم هذا على إسرائيل ولم يحرّم علينا. فإن كذّبوك فقل: ربكم ذو رحمة واسعة، ولذا لم يعاجلكم بالعقوبة، ولكن ليس معنى ذلك أنكم نجوتم من العذاب، فإن بأسه لا يُردّ عن القوم المجرمين.", "h": ["حرمة الميتة وأنواعها في سورة المائدة، وهي المنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع، وحرمة الدم المسفوح، ولحم الخنزير، وما أُهلّ لغير الله به، وما ذُبح على النصب، وحرّم بالسنة الحمر الأهلية والبغال، وكل ذي ناب من السباع وذي مخلب من الطيور.", "قد يُحرم العبد بالذنوب من كثير من الطيبات كما حصل لليهود.", "إمهال الله تعالى المجرمين لا يدل على عدم عقوبتهم، فإن بأس الله لا يُردّ عن القوم المجرمين."], "k": "«جزيناهم ببغيهم»… هل حُرمت خيراً كنت أجده، بذنب لم أتب منه بعد؟"}, {"lbl": "الآيات ١٤٨ – ١٥٠", "q": "سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمٖ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ ﴿١٤٨﴾ قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَٰلِغَةُۖ فَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ ﴿١٤٩﴾ قُلۡ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَهُم بِرَبِّهِمۡ يَعۡدِلُونَ ﴿١٥٠﴾", "w": [["أشركوا", "جعلوا لله شركاء يعبدونهم معه."], ["ولا حرّمنا من شيء", "مما حرّموه من البحائر والسوائب والوصائل والحامات."], ["ذاقوا بأسنا", "عذابنا."], ["تخرصون", "تكذبون."], ["الحجة البالغة", "الدليل القاطع للدعاوى الباطلة."], ["هلمّ شهداءكم", "أحضروهم."], ["يعدلون", "أي به غيره من الأصنام وسائر المعبودات الباطلة."]], "m": "ذكر الله شبهة للمشركين يتخذونها مبرراً لشركهم: لو شاء الله ما أشركنا ولا آباؤنا ولا حرّمنا من شيء، يريدون أن عدم مؤاخذته لهم دليل على رضاه وإلا لمنعهم. فردّها: كذلك كذّب الذين من قبلهم من الأمم حتى ذاقوا بأسنا، أخذهم أخذ عزيز مقتدر، فلو كان راضياً بشركهم لما أخذهم، فإمهال الله للناس لعلهم يتوبون ليس دليلاً على رضاه بالشرك والشر. قل هل عندكم من علم فتُخرجوه لنا؟ ليس لديكم علم، إن تتبعون إلا الظن وإن أنتم إلا تخرصون فتكذبون. قل فلله الحجة البالغة، فلو شاء هدايتكم لهداكم أجمعين، وإنما سنته في عباده أن يكلّفهم اختباراً، ويوضّح لهم الطريق، ويقيم الحجة عليهم، فمن اهتدى فلنفسه ومن ضلّ فعليها. قل هلمّ شهداءكم الذين يشهدون أن الله حرّم هذا، فإنهم لا يستطيعون، فإن شهدوا شهادة باطلة فلا تشهد معهم، بل بيّن بطلانها، ولا تتبع أهواء الذين كذّبوا بآياتنا والذين لا يؤمنون بالآخرة وهم بربهم يعدلون، وقد جمعوا هذه العظائم كلها، فكيف يجوز اتباعهم؟", "h": ["بطلان الاحتجاج بالقدر على فعل المعاصي والاستمرار فيها.", "لا حجة إلا فيما قام على أساس العلم الصحيح.", "الحكمة في عدم هداية الخلق كلهم مع قدرة الله تعالى على ذلك هو التكليف والابتلاء.", "مشروعية الشهادة وحضور الشهود.", "عدم إقرار شهادة الباطل، وحرمة السكوت عنها.", "حرمة اتباع أصحاب الأهواء الذين كذّبوا بآيات الله."], "k": "«لو شاء الله ما أشركنا»… هل أحتجّ بالقدر على تقصيري، والله قد أوضح لي الطريق وأقام عليّ الحجة؟"}, {"lbl": "الآيات ١٥١ – ١٥٣", "q": "۞قُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ ﴿١٥١﴾ وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿١٥٢﴾ وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ ﴿١٥٣﴾", "w": [["أتلُ", "اقرأ."], ["من إملاق", "من فقر."], ["الفواحش", "جمع فاحشة: كل ما قبُح واشتد قبحه كالزنى والبخل."], ["حرّم الله", "حرّم قتلها، وهي كل نفس إلا نفس الكافر المحارب."], ["إلا بالحق", "وهو النفس بالنفس، وزنى المحصن، والردة."], ["بالتي هي أحسن", "بالخصلة التي هي أحسن."], ["أشدّه", "الاحتلام مع سلامة العقل."], ["بالقسط", "بالعدل."], ["إلا وسعها", "طاقتها وما تتسع له."], ["تذكّرون", "تتذكّرون فتتّعظون."], ["السبل", "جمع سبيل، وهي الطريق."]], "m": "أمر الله رسوله أن يقول للمشركين: تعالوا أتلُ ما حرّم ربكم عليكم، لا ما حرّمتموه بأهوائكم. ففي الآية الأولى خمسة محرمات: ألّا تشركوا به شيئاً، وبالوالدين إحساناً، والأمر بالإحسان يقتضي تحريم الإساءة وهي العقوق، ولا تقتلوا أولادكم من فقر، نحن نرزقكم وإياهم، وفيها بشارة للأب الفقير أن الله سيرزقه وأطفاله فليصبر، ولا تقربوا الفواحش ما ظهر منها وما بطن، ويشمل كل خصلة اشتد قبحها قولاً أو فعلاً أو اعتقاداً، ولا تقتلوا النفس التي حرّم الله إلا بالحق، وهو القصاص، والزنى بعد الإحصان، والردة، لقوله ﷺ: «لا يحل دم امرئ مسلم إلا بإحدى ثلاث: النفس بالنفس، والثيب الزاني، والتارك لدينه المفارق للجماعة»، ذلكم وصّاكم به لعلكم تعقلون، فمن ارتكب هذه العظائم لا يُعدّ عاقلاً. وفي الثانية أربعة: لا تقربوا مال اليتيم إلا بالتي هي أحسن له نماءً وحفظاً حتى يبلغ أشدّه بالبلوغ عاقلاً، وأوفوا الكيل والميزان بالعدل، وحُرّم بذلك البخس والتطفيف، لا نكلّف نفساً إلا وسعها، رفعاً للحرج فيما نقص أو زاد بغير عمد، وإذا قلتم فاعدلوا ولو كان ذا قربى، فحرّم الجور وقول الزور وشهادته، وبعهد الله أوفوا، فحرّم نكث العهد وخلف الوعد، ذلكم وصّاكم به لعلكم تذكّرون. وفي الثالثة: وأن هذا صراطي مستقيماً فاتبعوه، أمر بالتزام الإسلام عقائد وعبادات وأحكاماً وأخلاقاً، ولا تتبعوا السبل من سائر الملل والنحل فتفرّق بكم عن سبيله، ذلكم وصّاكم به لعلكم تتقون غضب الرب وعذابه.", "h": ["هذه الوصايا العشر عليها مدار الإسلام وسعادة الإنسان في الدارين، وكان عبد الله بن مسعود يقول: «من سرّه أن ينظر إلى وصية رسول الله التي عليها خاتمه فليقرأ الآيات الثلاث من آخر سورة الأنعام: قل تعالوا… تتقون».", "حرمة الشرك، وعقوق الوالدين، وقتل الأولاد، والزنى واللواط، وكل قبيح من قول أو عمل أو اعتقاد، وقتل النفس إلا بالحق، وأكل مال اليتيم، وبخس الكيل والوزن، وقول الزور وشهادة الزور، ونكث العهد وخلف الوعد، والردة عن الإسلام، واتباع المذاهب الباطلة والطرق الضالة.", "كمال العقل باجتناب المحرمات الخمس الأولى.", "الحصول على ملكة المراقبة باجتناب المحرمات الأربع الثانية.", "النجاة من النار والخزي والعار في الدارين بالتزام الإسلام حتى الموت، والبراءة من غيره من سائر المذاهب والملل والطرق."], "k": "الوصايا العشر بين يديّ… أيّها أحتاج أن أراجع نفسي فيه اليوم: الوالدين، أم الكلمة العادلة، أم الوفاء بالوعد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 98;
insert into public.tdb_cards(topic, i, body) select 98, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٤٥ – ١٤٧", "q": "قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ رَبَّكَ غَفُورٞ رَّحِيمٞ ﴿١٤٥﴾ وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ ﴿١٤٦﴾ فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةٖ وَٰسِعَةٖ وَلَا يُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ ﴿١٤٧﴾", "w": [["محرّماً على طاعم يطعمه", "محظوراً ممنوعاً على آكل يأكله."], ["ميتة أو دماً مسفوحاً", "الميتة: ما مات دون تذكية، والدم المسفوح: المصبوب صباً، لا المختلط باللحم والعظام."], ["رجس", "نجس وقذر قبيح حرام."], ["أو فسقاً أُهلّ لغير الله به", "الفسق: الخروج عن طاعة الله، والمراد ما ذُبح ولم يُذكر اسم الله عليه، وإنما ذُكر عليه اسم الأصنام أو غيرها."], ["فمن اضطر غير باغ ولا عاد", "اضطُرّ: ألجأته الضرورة وهي خوف الهلاك، والباغي: الظالم، والعادي: المعتدي المجاوز للحد."], ["هادوا", "اليهود."], ["ذي ظفر", "صاحب ظفر، وهو الحيوان الذي لا يفرّق أصابعه كالإبل."], ["ما حملت ظهورهما أو الحوايا", "الشحم العالق بالظهر، والحوايا: المباعر والمصارين."], ["أو ما اختلط بعظم", "عُفي لهم عن الشحم المختلط بالعظم، كما عُفي عن الحوايا والعالق بالظهر."], ["ببغيهم", "بسبب ظلمهم."], ["ولا يُردّ بأسه", "بطشه وعذابه."]], "m": "ما زال السياق في الحجاج مع المحرّمين ما لم يحرّم الله، فأمر رسوله أن يقول: لا أجد فيما أوحي إليّ وأنا رسول الله شيئاً محرّماً على آكل يأكله إلا أن يكون ميتة لم تُذكَّ الذكاة الشرعية، أو دماً مصبوباً لا المختلط بالعظم واللحم كالكبد والطحال، أو لحم خنزير فإنه نجس قذر حرام، أو فسقاً ذُبح ولم يُذكر اسم الله عليه أو ذُكر عليه اسم الأصنام. فمن اضطُرّ غير باغ يأكلها تلذّذاً لا دفعاً للموت، ولا عاد متجاوز القدر الذي يدفع به الموت، فإن ربك غفور رحيم، ومن مغفرته ورحمته أنه أذن للمضطر بأكل الحرام في الضرورة. ثم أخبر أنه حرّم على اليهود كل ذي ظفر، ما ليس له أصابع مفرّقة كالإبل والنعام والبط والإوز، ومن البقر والغنم حرّم عليهم شحومهما اللاصقة بالكرش والكلى، إلا ما حملت ظهورهما أو الحوايا أو ما اختلط بعظم، ذلك جزيناهم ببغيهم، وإنا لصادقون فيما أخبرنا به عنهم، وهم الكاذبون إذ قالوا: إنما حرّم هذا على إسرائيل ولم يحرّم علينا. فإن كذّبوك فقل: ربكم ذو رحمة واسعة، ولذا لم يعاجلكم بالعقوبة، ولكن ليس معنى ذلك أنكم نجوتم من العذاب، فإن بأسه لا يُردّ عن القوم المجرمين.", "h": ["حرمة الميتة وأنواعها في سورة المائدة، وهي المنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع، وحرمة الدم المسفوح، ولحم الخنزير، وما أُهلّ لغير الله به، وما ذُبح على النصب، وحرّم بالسنة الحمر الأهلية والبغال، وكل ذي ناب من السباع وذي مخلب من الطيور.", "قد يُحرم العبد بالذنوب من كثير من الطيبات كما حصل لليهود.", "إمهال الله تعالى المجرمين لا يدل على عدم عقوبتهم، فإن بأس الله لا يُردّ عن القوم المجرمين."], "k": "«جزيناهم ببغيهم»… هل حُرمت خيراً كنت أجده، بذنب لم أتب منه بعد؟"}, {"lbl": "الآيات ١٤٨ – ١٥٠", "q": "سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمٖ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ ﴿١٤٨﴾ قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَٰلِغَةُۖ فَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ ﴿١٤٩﴾ قُلۡ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَهُم بِرَبِّهِمۡ يَعۡدِلُونَ ﴿١٥٠﴾", "w": [["أشركوا", "جعلوا لله شركاء يعبدونهم معه."], ["ولا حرّمنا من شيء", "مما حرّموه من البحائر والسوائب والوصائل والحامات."], ["ذاقوا بأسنا", "عذابنا."], ["تخرصون", "تكذبون."], ["الحجة البالغة", "الدليل القاطع للدعاوى الباطلة."], ["هلمّ شهداءكم", "أحضروهم."], ["يعدلون", "أي به غيره من الأصنام وسائر المعبودات الباطلة."]], "m": "ذكر الله شبهة للمشركين يتخذونها مبرراً لشركهم: لو شاء الله ما أشركنا ولا آباؤنا ولا حرّمنا من شيء، يريدون أن عدم مؤاخذته لهم دليل على رضاه وإلا لمنعهم. فردّها: كذلك كذّب الذين من قبلهم من الأمم حتى ذاقوا بأسنا، أخذهم أخذ عزيز مقتدر، فلو كان راضياً بشركهم لما أخذهم، فإمهال الله للناس لعلهم يتوبون ليس دليلاً على رضاه بالشرك والشر. قل هل عندكم من علم فتُخرجوه لنا؟ ليس لديكم علم، إن تتبعون إلا الظن وإن أنتم إلا تخرصون فتكذبون. قل فلله الحجة البالغة، فلو شاء هدايتكم لهداكم أجمعين، وإنما سنته في عباده أن يكلّفهم اختباراً، ويوضّح لهم الطريق، ويقيم الحجة عليهم، فمن اهتدى فلنفسه ومن ضلّ فعليها. قل هلمّ شهداءكم الذين يشهدون أن الله حرّم هذا، فإنهم لا يستطيعون، فإن شهدوا شهادة باطلة فلا تشهد معهم، بل بيّن بطلانها، ولا تتبع أهواء الذين كذّبوا بآياتنا والذين لا يؤمنون بالآخرة وهم بربهم يعدلون، وقد جمعوا هذه العظائم كلها، فكيف يجوز اتباعهم؟", "h": ["بطلان الاحتجاج بالقدر على فعل المعاصي والاستمرار فيها.", "لا حجة إلا فيما قام على أساس العلم الصحيح.", "الحكمة في عدم هداية الخلق كلهم مع قدرة الله تعالى على ذلك هو التكليف والابتلاء.", "مشروعية الشهادة وحضور الشهود.", "عدم إقرار شهادة الباطل، وحرمة السكوت عنها.", "حرمة اتباع أصحاب الأهواء الذين كذّبوا بآيات الله."], "k": "«لو شاء الله ما أشركنا»… هل أحتجّ بالقدر على تقصيري، والله قد أوضح لي الطريق وأقام عليّ الحجة؟"}, {"lbl": "الآيات ١٥١ – ١٥٣", "q": "۞قُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ ﴿١٥١﴾ وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿١٥٢﴾ وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ ﴿١٥٣﴾", "w": [["أتلُ", "اقرأ."], ["من إملاق", "من فقر."], ["الفواحش", "جمع فاحشة: كل ما قبُح واشتد قبحه كالزنى والبخل."], ["حرّم الله", "حرّم قتلها، وهي كل نفس إلا نفس الكافر المحارب."], ["إلا بالحق", "وهو النفس بالنفس، وزنى المحصن، والردة."], ["بالتي هي أحسن", "بالخصلة التي هي أحسن."], ["أشدّه", "الاحتلام مع سلامة العقل."], ["بالقسط", "بالعدل."], ["إلا وسعها", "طاقتها وما تتسع له."], ["تذكّرون", "تتذكّرون فتتّعظون."], ["السبل", "جمع سبيل، وهي الطريق."]], "m": "أمر الله رسوله أن يقول للمشركين: تعالوا أتلُ ما حرّم ربكم عليكم، لا ما حرّمتموه بأهوائكم. ففي الآية الأولى خمسة محرمات: ألّا تشركوا به شيئاً، وبالوالدين إحساناً، والأمر بالإحسان يقتضي تحريم الإساءة وهي العقوق، ولا تقتلوا أولادكم من فقر، نحن نرزقكم وإياهم، وفيها بشارة للأب الفقير أن الله سيرزقه وأطفاله فليصبر، ولا تقربوا الفواحش ما ظهر منها وما بطن، ويشمل كل خصلة اشتد قبحها قولاً أو فعلاً أو اعتقاداً، ولا تقتلوا النفس التي حرّم الله إلا بالحق، وهو القصاص، والزنى بعد الإحصان، والردة، لقوله ﷺ: «لا يحل دم امرئ مسلم إلا بإحدى ثلاث: النفس بالنفس، والثيب الزاني، والتارك لدينه المفارق للجماعة»، ذلكم وصّاكم به لعلكم تعقلون، فمن ارتكب هذه العظائم لا يُعدّ عاقلاً. وفي الثانية أربعة: لا تقربوا مال اليتيم إلا بالتي هي أحسن له نماءً وحفظاً حتى يبلغ أشدّه بالبلوغ عاقلاً، وأوفوا الكيل والميزان بالعدل، وحُرّم بذلك البخس والتطفيف، لا نكلّف نفساً إلا وسعها، رفعاً للحرج فيما نقص أو زاد بغير عمد، وإذا قلتم فاعدلوا ولو كان ذا قربى، فحرّم الجور وقول الزور وشهادته، وبعهد الله أوفوا، فحرّم نكث العهد وخلف الوعد، ذلكم وصّاكم به لعلكم تذكّرون. وفي الثالثة: وأن هذا صراطي مستقيماً فاتبعوه، أمر بالتزام الإسلام عقائد وعبادات وأحكاماً وأخلاقاً، ولا تتبعوا السبل من سائر الملل والنحل فتفرّق بكم عن سبيله، ذلكم وصّاكم به لعلكم تتقون غضب الرب وعذابه.", "h": ["هذه الوصايا العشر عليها مدار الإسلام وسعادة الإنسان في الدارين، وكان عبد الله بن مسعود يقول: «من سرّه أن ينظر إلى وصية رسول الله التي عليها خاتمه فليقرأ الآيات الثلاث من آخر سورة الأنعام: قل تعالوا… تتقون».", "حرمة الشرك، وعقوق الوالدين، وقتل الأولاد، والزنى واللواط، وكل قبيح من قول أو عمل أو اعتقاد، وقتل النفس إلا بالحق، وأكل مال اليتيم، وبخس الكيل والوزن، وقول الزور وشهادة الزور، ونكث العهد وخلف الوعد، والردة عن الإسلام، واتباع المذاهب الباطلة والطرق الضالة.", "كمال العقل باجتناب المحرمات الخمس الأولى.", "الحصول على ملكة المراقبة باجتناب المحرمات الأربع الثانية.", "النجاة من النار والخزي والعار في الدارين بالتزام الإسلام حتى الموت، والبراءة من غيره من سائر المذاهب والملل والطرق."], "k": "الوصايا العشر بين يديّ… أيّها أحتاج أن أراجع نفسي فيه اليوم: الوالدين، أم الكلمة العادلة، أم الوفاء بالوعد؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (99, 6, 154, 165, 'سورة الأنعام ١٥٤ – ١٦٥', '«وهذا كتاب أنزلناه مبارك»، «يوم يأتي بعض آيات ربك»، و«قل إن صلاتي ونسكي ومحياي ومماتي لله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 99) = $j$[{"lbl": "الآيات ١٥٤ – ١٥٧", "q": "ثُمَّ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ تَمَامًا عَلَى ٱلَّذِيٓ أَحۡسَنَ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمۡ يُؤۡمِنُونَ ﴿١٥٤﴾ وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ فَٱتَّبِعُوهُ وَٱتَّقُواْ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿١٥٥﴾ أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ٱلۡكِتَٰبُ عَلَىٰ طَآئِفَتَيۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَٰفِلِينَ ﴿١٥٦﴾ أَوۡ تَقُولُواْ لَوۡ أَنَّآ أُنزِلَ عَلَيۡنَا ٱلۡكِتَٰبُ لَكُنَّآ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَآءَكُم بَيِّنَةٞ مِّن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِي ٱلَّذِينَ يَصۡدِفُونَ عَنۡ ءَايَٰتِنَا سُوٓءَ ٱلۡعَذَابِ بِمَا كَانُواْ يَصۡدِفُونَ ﴿١٥٧﴾", "w": [["الكتاب", "التوراة."], ["وتفصيلاً لكل شيء", "مما تحتاج إليه أمة بني إسرائيل في عقائدها وعباداتها وفضائلها وأحكامها."], ["وهذا كتاب أنزلناه", "القرآن الكريم."], ["مبارك", "خيريته ونفعه وبركته دائمة."], ["على طائفتين من قبلنا", "اليهود والنصارى."], ["عن دراستهم", "قراءتهم لكتبهم، لأنها بلسانهم ونحن لا نفهم ذلك."], ["وصدف عنها", "أعرض عنها ولم يلتفت إليها."], ["سوء العذاب", "سيئ العذاب، وهو أشده."]], "m": "هذا الكلام متصل بما قبله: قل تعالوا أتلُ ما حرّم ربكم، ثم أتلُ أن ربي آتى موسى الكتاب تماماً لنعمه على الذي أحسن طاعة ربه، وهو موسى ﵇، وتفصيلاً لكل شيء تحتاج إليه أمة بني إسرائيل، وهدى يتبيّنون به الحق، ورحمة لهم، لعلهم بلقاء ربهم يؤمنون فيعملون الصالحات. وهذا كتاب أنزلناه مبارك، ينال بركته كل من آمن به وعمل به وتلاه تعبّداً وتعلّماً، فاتبعوه في عقائده وعباداته وأحكامه، فإنه يقود إلى السعادة والكمال في الحياتين، واتقوا ترك العمل به لعلكم ترحمون. أنزلناه لئلا تقولوا يوم القيامة: إنما أُنزل الكتاب على اليهود والنصارى، وكنا عن دراستهم لغافلين لا نعرف لغتهم، أو تقولوا: لو أنا أُنزل علينا الكتاب لكنا أهدى منهم، فقد جاءكم بيّنة من ربكم، القرآن ورسوله المبلّغ له، وهدى ورحمة، فأي حجة بقيت لكم؟ فمن أظلم ممن كذّب بآيات الله وصدف عنها؟ سنجزي الذين يصدفون عن آياتنا سوء العذاب بما كانوا يصدفون.", "h": ["بيان منّة الله تعالى على موسى ﵇، والثناء عليه لإحسانه.", "تقرير عقيدة البعث والجزاء يوم القيامة.", "الإشادة بالقرآن الكريم، وما أودع الله فيه من البركة والهدى والرحمة والخير.", "قطع حجة المشركين بإنزال الله تعالى كتابه وإرسال رسوله محمد ﷺ.", "التنديد بالظلم، وبيان جزاء الظالمين المكذبين بآيات الله المعرضين عنها."], "k": "«وهذا كتاب أنزلناه مبارك فاتبعوه»… هل أطلب بركة القرآن بالتلاوة وحدها، أم بالاتباع أيضاً؟"}, {"lbl": "الآيات ١٥٨ – ١٦٠", "q": "هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَـٰٓئِكَةُ أَوۡ يَأۡتِيَ رَبُّكَ أَوۡ يَأۡتِيَ بَعۡضُ ءَايَٰتِ رَبِّكَۗ يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ ﴿١٥٨﴾ إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ إِنَّمَآ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفۡعَلُونَ ﴿١٥٩﴾ مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَمُونَ ﴿١٦٠﴾", "w": [["بعض آيات ربك", "علامات الساعة، منها طلوع الشمس من مغربها."], ["كسبت في إيمانها خيراً", "الطاعات والقربات."], ["فرّقوا دينهم", "جعلوه طرائق ومذاهب تتعادى."], ["وكانوا شيعاً", "طوائف وأحزاباً."], ["من جاء بالحسنة", "أتى يوم القيامة بالحسنة التي هي الإيمان بالله والإقرار بوحدانيته والعمل بطاعته وطاعة رسوله."], ["ومن جاء بالسيئة", "أي بالشرك بالله ومعاصيه."]], "m": "بعد الحجج والآيات، ما زال المشركون في موقفهم المعادي للحق، فقال الله: هل ينتظرون إلا أن تأتيهم الملائكة لقبض أرواحهم، أو يأتي ربك يوم القيامة لفصل القضاء، أو يأتي بعض آيات ربك الدالة على قرب الساعة كطلوع الشمس من مغربها؟ يوم يأتي ذلك لا ينفع نفساً إيمانها لم تكن آمنت من قبل، لأنه أصبح إيماناً اضطرارياً لا اختيارياً، أو نفساً آمنت ولم تكسب في إيمانها خيراً فأرادت أن تكسبه، فإن باب التوبة مفتوح إلى يوم طلوع الشمس من مغربها فيُغلق. قل انتظروا إنا منتظرون ساعة هلاككم فإنها آتية لا محالة. إن الذين فرّقوا دينهم وكانوا شيعاً وفرقاً مختلفة كاليهود والنصارى، ومن يبتدع من هذه الأمة بدعاً فيُتابع عليها فيصيرون فرقاً متطاحنة، لست منهم في شيء، أنت بريء منهم، إنما أمرهم إلى الله ثم ينبّئهم بما كانوا يفعلون. من جاء بالحسنة فله عشر أمثالها، ومن جاء بالسيئة فلا يُجزى إلا مثلها، وهم لا يُظلمون، فلا يُنقص المحسن حسنة، ولا يُضاف إلى سيئاته سيئة ما عملها.", "h": ["إثبات صفة الإتيان في عرصات القيامة للرب تبارك وتعالى لفصل القضاء.", "تقرير أشراط الساعة، وأن طلوع الشمس منها، وأنها متى ظهرت أُغلق باب التوبة.", "حرمة الفرقة في الدين، وأن اليهود والنصارى فرّقوا دينهم، وأن أمة الإسلام أصابتها الفرقة كذلك بل وهي أكثر، لحديث: «وستفترق هذه الأمة على ثلاث وسبعين فرقة».", "براءة الرسول ﷺ ممن فرّقوا دينهم، وترك الأمر لله يحكم بينهم بحكمه العادل.", "مضاعفة الحسنات وعدم مضاعفة السيئات عدل من الله ورحمة."], "k": "«فله عشر أمثالها»… ربي يضاعف الحسنة عشراً؛ فكم حسنة سهلة فوّتّها اليوم؟"}, {"lbl": "الآيات ١٦١ – ١٦٥", "q": "قُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٦١﴾ قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٦٢﴾ لَا شَرِيكَ لَهُۥۖ وَبِذَٰلِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِينَ ﴿١٦٣﴾ قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبّٗا وَهُوَ رَبُّ كُلِّ شَيۡءٖۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿١٦٤﴾ وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَـٰٓئِفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ ﴿١٦٥﴾", "w": [["قِيَماً", "أي مستقيماً."], ["ملة إبراهيم", "دين إبراهيم، وهو الإسلام."], ["حنيفاً", "مائلاً عن الضلالة إلى الهدى."], ["ونسكي", "ذبحي تقرّباً إلى الله تعالى."], ["أبغي رباً", "أطلب رباً، أي معبوداً أعبده."], ["ولا تزر وازرة", "لا تحمل نفس وازرة، أي آثمة."], ["وزر أخرى", "إثم نفس أخرى."], ["خلائف الأرض", "يخلف بعضكم بعضاً، جيل يموت وآخر يحيا إلى نهاية الحياة."], ["ليبلوكم فيما آتاكم", "ليختبركم فيما أعطاكم من الصحة والمرض، والمال والفقر، والعلم والجهل."]], "m": "في خاتمة هذه السورة التي كانت كلها في الحجاج مع العادلين بربهم وبيان طريق الهدى لهم، أمر الله رسوله أن يعلن مفاصلته للمشركين: قل إنني هداني ربي إلى صراط مستقيم، ديناً قيّماً ملة إبراهيم حنيفاً وما كان من المشركين، قل إن صلاتي ونسكي، ما أذبحه تقرّباً إلى ربي، ومحياي، ما آتيه في حياتي، ومماتي، ما أموت عليه من الطاعات، لله رب العالمين وحده لا شريك له، وبذلك أمرني ربي، وأنا أول المسلمين. وأمره أن ينكر على المشركين دعوتهم له أن يعبد معهم آلهتهم: قل أغير الله أبغي رباً وهو رب كل شيء، خالقه ورازقه وحافظه؟ ولا تكسب كل نفس من شر إلا عليها، ولا تحمل نفس مذنبة ذنب أخرى، ثم إلى ربكم مرجعكم فينبّئكم بما كنتم فيه تختلفون ويقضي بينكم. وهو الذي جعلكم خلائف الأرض، يموت هذا فيُورث، ثم يموت الوارث فيُورث، ورفع بعضكم فوق بعض درجات: غني وفقير، صحيح وضرير، عالم وجاهل، ليبلوكم فيما آتاكم فيُرى الشاكر والكافر، إن ربك سريع العقاب للكافر، وإنه لغفور رحيم للشاكر.", "h": ["ملة إبراهيم ﵇ هي الإسلام.", "مشروعية قول «إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين» في القيام للصلاة.", "لا يصح طلب رب غير الله تعالى، لأنه رب كل شيء.", "عدالة الله تعالى تتجلّى يوم القيامة.", "عدالة الجزاء يوم القيامة.", "تفاوت الناس في الغنى والفقر، والصحة والمرض، والبر والفجور، وفي كل شيء مظهر من مظاهر تدبير الله تعالى في خلقه، ينتفع به الذاكرون من غير أصحاب الغفلة والنسيان."], "k": "«ومحياي ومماتي لله رب العالمين»… لو عُرضت عليّ حياتي اليوم، كم منها كان لله حقاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 99;
insert into public.tdb_cards(topic, i, body) select 99, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥٤ – ١٥٧", "q": "ثُمَّ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ تَمَامًا عَلَى ٱلَّذِيٓ أَحۡسَنَ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمۡ يُؤۡمِنُونَ ﴿١٥٤﴾ وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ فَٱتَّبِعُوهُ وَٱتَّقُواْ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿١٥٥﴾ أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ٱلۡكِتَٰبُ عَلَىٰ طَآئِفَتَيۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَٰفِلِينَ ﴿١٥٦﴾ أَوۡ تَقُولُواْ لَوۡ أَنَّآ أُنزِلَ عَلَيۡنَا ٱلۡكِتَٰبُ لَكُنَّآ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَآءَكُم بَيِّنَةٞ مِّن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِي ٱلَّذِينَ يَصۡدِفُونَ عَنۡ ءَايَٰتِنَا سُوٓءَ ٱلۡعَذَابِ بِمَا كَانُواْ يَصۡدِفُونَ ﴿١٥٧﴾", "w": [["الكتاب", "التوراة."], ["وتفصيلاً لكل شيء", "مما تحتاج إليه أمة بني إسرائيل في عقائدها وعباداتها وفضائلها وأحكامها."], ["وهذا كتاب أنزلناه", "القرآن الكريم."], ["مبارك", "خيريته ونفعه وبركته دائمة."], ["على طائفتين من قبلنا", "اليهود والنصارى."], ["عن دراستهم", "قراءتهم لكتبهم، لأنها بلسانهم ونحن لا نفهم ذلك."], ["وصدف عنها", "أعرض عنها ولم يلتفت إليها."], ["سوء العذاب", "سيئ العذاب، وهو أشده."]], "m": "هذا الكلام متصل بما قبله: قل تعالوا أتلُ ما حرّم ربكم، ثم أتلُ أن ربي آتى موسى الكتاب تماماً لنعمه على الذي أحسن طاعة ربه، وهو موسى ﵇، وتفصيلاً لكل شيء تحتاج إليه أمة بني إسرائيل، وهدى يتبيّنون به الحق، ورحمة لهم، لعلهم بلقاء ربهم يؤمنون فيعملون الصالحات. وهذا كتاب أنزلناه مبارك، ينال بركته كل من آمن به وعمل به وتلاه تعبّداً وتعلّماً، فاتبعوه في عقائده وعباداته وأحكامه، فإنه يقود إلى السعادة والكمال في الحياتين، واتقوا ترك العمل به لعلكم ترحمون. أنزلناه لئلا تقولوا يوم القيامة: إنما أُنزل الكتاب على اليهود والنصارى، وكنا عن دراستهم لغافلين لا نعرف لغتهم، أو تقولوا: لو أنا أُنزل علينا الكتاب لكنا أهدى منهم، فقد جاءكم بيّنة من ربكم، القرآن ورسوله المبلّغ له، وهدى ورحمة، فأي حجة بقيت لكم؟ فمن أظلم ممن كذّب بآيات الله وصدف عنها؟ سنجزي الذين يصدفون عن آياتنا سوء العذاب بما كانوا يصدفون.", "h": ["بيان منّة الله تعالى على موسى ﵇، والثناء عليه لإحسانه.", "تقرير عقيدة البعث والجزاء يوم القيامة.", "الإشادة بالقرآن الكريم، وما أودع الله فيه من البركة والهدى والرحمة والخير.", "قطع حجة المشركين بإنزال الله تعالى كتابه وإرسال رسوله محمد ﷺ.", "التنديد بالظلم، وبيان جزاء الظالمين المكذبين بآيات الله المعرضين عنها."], "k": "«وهذا كتاب أنزلناه مبارك فاتبعوه»… هل أطلب بركة القرآن بالتلاوة وحدها، أم بالاتباع أيضاً؟"}, {"lbl": "الآيات ١٥٨ – ١٦٠", "q": "هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَـٰٓئِكَةُ أَوۡ يَأۡتِيَ رَبُّكَ أَوۡ يَأۡتِيَ بَعۡضُ ءَايَٰتِ رَبِّكَۗ يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ ﴿١٥٨﴾ إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ إِنَّمَآ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفۡعَلُونَ ﴿١٥٩﴾ مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَمُونَ ﴿١٦٠﴾", "w": [["بعض آيات ربك", "علامات الساعة، منها طلوع الشمس من مغربها."], ["كسبت في إيمانها خيراً", "الطاعات والقربات."], ["فرّقوا دينهم", "جعلوه طرائق ومذاهب تتعادى."], ["وكانوا شيعاً", "طوائف وأحزاباً."], ["من جاء بالحسنة", "أتى يوم القيامة بالحسنة التي هي الإيمان بالله والإقرار بوحدانيته والعمل بطاعته وطاعة رسوله."], ["ومن جاء بالسيئة", "أي بالشرك بالله ومعاصيه."]], "m": "بعد الحجج والآيات، ما زال المشركون في موقفهم المعادي للحق، فقال الله: هل ينتظرون إلا أن تأتيهم الملائكة لقبض أرواحهم، أو يأتي ربك يوم القيامة لفصل القضاء، أو يأتي بعض آيات ربك الدالة على قرب الساعة كطلوع الشمس من مغربها؟ يوم يأتي ذلك لا ينفع نفساً إيمانها لم تكن آمنت من قبل، لأنه أصبح إيماناً اضطرارياً لا اختيارياً، أو نفساً آمنت ولم تكسب في إيمانها خيراً فأرادت أن تكسبه، فإن باب التوبة مفتوح إلى يوم طلوع الشمس من مغربها فيُغلق. قل انتظروا إنا منتظرون ساعة هلاككم فإنها آتية لا محالة. إن الذين فرّقوا دينهم وكانوا شيعاً وفرقاً مختلفة كاليهود والنصارى، ومن يبتدع من هذه الأمة بدعاً فيُتابع عليها فيصيرون فرقاً متطاحنة، لست منهم في شيء، أنت بريء منهم، إنما أمرهم إلى الله ثم ينبّئهم بما كانوا يفعلون. من جاء بالحسنة فله عشر أمثالها، ومن جاء بالسيئة فلا يُجزى إلا مثلها، وهم لا يُظلمون، فلا يُنقص المحسن حسنة، ولا يُضاف إلى سيئاته سيئة ما عملها.", "h": ["إثبات صفة الإتيان في عرصات القيامة للرب تبارك وتعالى لفصل القضاء.", "تقرير أشراط الساعة، وأن طلوع الشمس منها، وأنها متى ظهرت أُغلق باب التوبة.", "حرمة الفرقة في الدين، وأن اليهود والنصارى فرّقوا دينهم، وأن أمة الإسلام أصابتها الفرقة كذلك بل وهي أكثر، لحديث: «وستفترق هذه الأمة على ثلاث وسبعين فرقة».", "براءة الرسول ﷺ ممن فرّقوا دينهم، وترك الأمر لله يحكم بينهم بحكمه العادل.", "مضاعفة الحسنات وعدم مضاعفة السيئات عدل من الله ورحمة."], "k": "«فله عشر أمثالها»… ربي يضاعف الحسنة عشراً؛ فكم حسنة سهلة فوّتّها اليوم؟"}, {"lbl": "الآيات ١٦١ – ١٦٥", "q": "قُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٦١﴾ قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٦٢﴾ لَا شَرِيكَ لَهُۥۖ وَبِذَٰلِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِينَ ﴿١٦٣﴾ قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبّٗا وَهُوَ رَبُّ كُلِّ شَيۡءٖۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿١٦٤﴾ وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَـٰٓئِفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ ﴿١٦٥﴾", "w": [["قِيَماً", "أي مستقيماً."], ["ملة إبراهيم", "دين إبراهيم، وهو الإسلام."], ["حنيفاً", "مائلاً عن الضلالة إلى الهدى."], ["ونسكي", "ذبحي تقرّباً إلى الله تعالى."], ["أبغي رباً", "أطلب رباً، أي معبوداً أعبده."], ["ولا تزر وازرة", "لا تحمل نفس وازرة، أي آثمة."], ["وزر أخرى", "إثم نفس أخرى."], ["خلائف الأرض", "يخلف بعضكم بعضاً، جيل يموت وآخر يحيا إلى نهاية الحياة."], ["ليبلوكم فيما آتاكم", "ليختبركم فيما أعطاكم من الصحة والمرض، والمال والفقر، والعلم والجهل."]], "m": "في خاتمة هذه السورة التي كانت كلها في الحجاج مع العادلين بربهم وبيان طريق الهدى لهم، أمر الله رسوله أن يعلن مفاصلته للمشركين: قل إنني هداني ربي إلى صراط مستقيم، ديناً قيّماً ملة إبراهيم حنيفاً وما كان من المشركين، قل إن صلاتي ونسكي، ما أذبحه تقرّباً إلى ربي، ومحياي، ما آتيه في حياتي، ومماتي، ما أموت عليه من الطاعات، لله رب العالمين وحده لا شريك له، وبذلك أمرني ربي، وأنا أول المسلمين. وأمره أن ينكر على المشركين دعوتهم له أن يعبد معهم آلهتهم: قل أغير الله أبغي رباً وهو رب كل شيء، خالقه ورازقه وحافظه؟ ولا تكسب كل نفس من شر إلا عليها، ولا تحمل نفس مذنبة ذنب أخرى، ثم إلى ربكم مرجعكم فينبّئكم بما كنتم فيه تختلفون ويقضي بينكم. وهو الذي جعلكم خلائف الأرض، يموت هذا فيُورث، ثم يموت الوارث فيُورث، ورفع بعضكم فوق بعض درجات: غني وفقير، صحيح وضرير، عالم وجاهل، ليبلوكم فيما آتاكم فيُرى الشاكر والكافر، إن ربك سريع العقاب للكافر، وإنه لغفور رحيم للشاكر.", "h": ["ملة إبراهيم ﵇ هي الإسلام.", "مشروعية قول «إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين» في القيام للصلاة.", "لا يصح طلب رب غير الله تعالى، لأنه رب كل شيء.", "عدالة الله تعالى تتجلّى يوم القيامة.", "عدالة الجزاء يوم القيامة.", "تفاوت الناس في الغنى والفقر، والصحة والمرض، والبر والفجور، وفي كل شيء مظهر من مظاهر تدبير الله تعالى في خلقه، ينتفع به الذاكرون من غير أصحاب الغفلة والنسيان."], "k": "«ومحياي ومماتي لله رب العالمين»… لو عُرضت عليّ حياتي اليوم، كم منها كان لله حقاً؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;